function toFaDigits(val) {
  return String(val).replace(/\d/g, (d) => "\u06F0\u06F1\u06F2\u06F3\u06F4\u06F5\u06F6\u06F7\u06F8\u06F9"[Number(d)]);
}
__name(toFaDigits, "toFaDigits");
function buildHood([
  id,
  name,
  zone,
  lat,
  lng,
  buyPerSqm,
  rahn80m,
  air,
  powerWater,
  internet,
  metro,
  security,
  flatTerrain,
  pros,
  cons,
  phonePrefix,
  street
]) {
  const discSqm = Math.max(12, Math.round(buyPerSqm * 0.85));
  const totalBillion = toFaDigits((discSqm * 95 / 1e3).toFixed(2));
  const profitMill = toFaDigits(Math.max(150, Math.round((buyPerSqm - discSqm) * 95)));
  return {
    id,
    name,
    zone,
    lat,
    lng,
    radius: 1150,
    buyPerSqm,
    rahn80m,
    air,
    powerWater,
    internet,
    metro,
    security,
    flatTerrain,
    pros,
    cons,
    sponsor: {
      name: `\u062F\u067E\u0627\u0631\u062A\u0645\u0627\u0646 \u0627\u0645\u0644\u0627\u06A9 \u0645\u0631\u06A9\u0632\u06CC ${name}`,
      phone: `${phonePrefix}-32204400`,
      specialty: `\u0648\u0627\u062D\u062F\u0647\u0627\u06CC \u0645\u0633\u06A9\u0648\u0646\u06CC \u0648 \u0633\u0631\u0645\u0627\u06CC\u0647\u200C\u06AF\u0630\u0627\u0631\u06CC ${street}`,
      experienceYears: 14
    },
    trafficInfo: {
      liveStatus: `\u062A\u0631\u062F\u062F \u0631\u0648\u0627\u0646 \u062F\u0631 \u0645\u062D\u0648\u0631\u0647\u0627\u06CC \u0627\u0635\u0644\u06CC ${name} \u0648 ${street}`,
      liveSeverity: metro >= 8 ? "semi" : "smooth",
      peakHours: "\u06F1\u06F7:\u06F3\u06F0 \u062A\u0627 \u06F2\u06F0:\u06F3\u06F0",
      seasonalAnalysis: "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u0645\u062A\u0639\u0627\u062F\u0644 \u0634\u0647\u0631\u06CC \u062F\u0631 \u0637\u0648\u0644 \u0633\u0627\u0644",
      bottlenecks: `\u0645\u06CC\u062F\u0627\u0646 \u0645\u0631\u06A9\u0632\u06CC \u0648 \u062A\u0642\u0627\u0637\u0639 ${street}`,
      trafficScore: 7.9
    },
    bargains: [
      {
        id: `ext-hood-${id}-1`,
        title: `\u06F9\u06F5 \u0645\u062A\u0631\u06CC \u06F2 \u062E\u0648\u0627\u0628 \u0646\u0648\u0633\u0627\u0632 \u062F\u0631 ${name} (${street})\u060C \u0633\u0646\u062F \u062A\u06A9\u200C\u0628\u0631\u06AF`,
        type: "\u062E\u0631\u06CC\u062F",
        sqm: 95,
        priceText: `\u0645\u062A\u0631\u06CC ${toFaDigits(discSqm)} \u0645\u06CC\u0644\u06CC\u0648\u0646 \u062A\u0648\u0645\u0627\u0646 (\u06A9\u0644: ${totalBillion} \u0645\u06CC\u0644\u06CC\u0627\u0631\u062F)`,
        discountPercent: 15,
        buyerProfitText: `${profitMill} \u0645\u06CC\u0644\u06CC\u0648\u0646 \u062A\u0648\u0645\u0627\u0646 \u0632\u06CC\u0631 \u0645\u06CC\u0627\u0646\u06AF\u06CC\u0646 \u0645\u062D\u0644\u0647`,
        street
      }
    ]
  };
}
__name(buildHood, "buildHood");
var KARAJ_SEEDS = [
  [107, "\u0628\u0627\u063A\u0633\u062A\u0627\u0646", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u06A9\u0631\u062C (\u0645\u0646\u0637\u0642\u0647 \u06F6)", 35.8765, 50.9425, 78, 880, 9, 8.6, 8.5, 6.2, 8.6, 7.2, "\u0647\u0648\u0627\u06CC \u067E\u0627\u06A9 \u06A9\u0648\u0647\u067E\u0627\u06CC\u0647\u200C\u0627\u06CC\u060C \u0622\u067E\u0627\u0631\u062A\u0645\u0627\u0646\u200C\u0647\u0627\u06CC \u0646\u0648\u0633\u0627\u0632 \u063A\u0631\u0628\u06CC", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0645\u062A\u0631\u0648 \u06A9\u0631\u062C", "026", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0645\u0627\u0645 \u062E\u0645\u06CC\u0646\u06CC \u0628\u0627\u063A\u0633\u062A\u0627\u0646"],
  [108, "\u06AF\u0644\u0634\u0647\u0631 \u0648\u06CC\u0644\u0627 \u0648 \u062F\u0631\u062E\u062A\u06CC", "\u063A\u0631\u0628 \u06A9\u0631\u062C (\u0645\u0646\u0637\u0642\u0647 \u06F5)", 35.8165, 50.9465, 82, 940, 8.4, 8.7, 8.9, 9.5, 8.6, 8.9, "\u0628\u0644\u0648\u0627\u0631 \u062D\u062F\u0627\u062F\u06CC\u060C \u062E\u06CC\u0627\u0628\u0627\u0646 \u062F\u0631\u062E\u062A\u06CC \u0648 \u06AF\u0644\u0634\u0647\u0631 \u0648\u06CC\u0644\u0627\u060C \u062F\u0633\u062A\u0631\u0633\u06CC \u0633\u0631\u06CC\u0639 \u0628\u0647 \u0645\u062A\u0631\u0648 \u0648 \u0627\u062A\u0648\u0628\u0627\u0646", "\u067E\u0631\u062A\u0631\u062F\u062F \u0628\u0648\u062F\u0646 \u0686\u0647\u0627\u0631\u0631\u0627\u0647 \u06AF\u0644\u0632\u0627\u0631 \u0648 \u0645\u06CC\u062F\u0627\u0646 \u0645\u0627\u062F\u0631", "026", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u062F\u0631\u062E\u062A\u06CC \u0648 \u06AF\u0644\u0634\u0647\u0631 \u0648\u06CC\u0644\u0627"],
  [109, "\u0634\u0627\u0647\u06CC\u0646\u200C\u0648\u06CC\u0644\u0627", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u06A9\u0631\u062C (\u0645\u0646\u0637\u0642\u0647 \u06F6)", 35.859, 50.9495, 74, 840, 8.5, 8.5, 8.6, 6.8, 8.4, 8.6, "\u0628\u0627\u0641\u062A \u0634\u0647\u0631\u06CC \u0641\u0639\u0627\u0644\u060C \u0642\u06CC\u0645\u062A \u0645\u0646\u0627\u0633\u0628 \u0648 \u0646\u0642\u062F\u0634\u0648\u0646\u062F\u06AF\u06CC \u0633\u0631\u06CC\u0639", "\u062A\u0631\u0627\u06A9\u0645 \u0628\u0627\u0644\u0627\u06CC \u062E\u06CC\u0627\u0628\u0627\u0646 \u0627\u0635\u0644\u06CC", "026", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0627\u0635\u0644\u06CC \u0634\u0627\u0647\u06CC\u0646\u200C\u0648\u06CC\u0644\u0627"],
  [110, "\u0645\u0647\u0631\u0648\u06CC\u0644\u0627", "\u0645\u0631\u06A9\u0632 \u06A9\u0631\u062C (\u0645\u0646\u0637\u0642\u0647 \u06F8)", 35.824, 50.962, 94, 1080, 8.5, 8.9, 9, 8.4, 9, 9, "\u062E\u06CC\u0627\u0628\u0627\u0646 \u062F\u0631\u062E\u062A\u06CC \u0648 \u0627\u0646\u0648\u0634\u06CC\u0631\u0648\u0627\u0646\u060C \u062F\u0633\u062A\u0631\u0633\u06CC \u0639\u0627\u0644\u06CC \u0628\u0647 \u0628\u0632\u0631\u06AF\u0631\u0627\u0647 \u0648 \u0645\u0631\u0627\u06A9\u0632 \u062E\u0631\u06CC\u062F", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u0639\u0635\u0631\u06AF\u0627\u0647\u06CC \u0645\u06CC\u062F\u0627\u0646 \u0645\u0627\u062F\u0631", "026", "\u0628\u0644\u0648\u0627\u0631 \u0645\u0639\u0644\u0645 \u0648 \u0627\u0646\u0648\u0634\u06CC\u0631\u0648\u0627\u0646"],
  [111, "\u06A9\u06CC\u0627\u0646\u0645\u0647\u0631", "\u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u06A9\u0631\u062C (\u0645\u0646\u0637\u0642\u0647 \u06F1\u06F2)", 35.764, 50.892, 58, 660, 8.7, 8.2, 8.3, 6, 8.1, 9.2, "\u0646\u0648\u0633\u0627\u0632 \u0648 \u0631\u0648 \u0628\u0647 \u0631\u0634\u062F \u062F\u0631 \u0645\u062C\u0627\u0648\u0631\u062A \u0645\u0647\u0631\u0634\u0647\u0631\u060C \u0642\u06CC\u0645\u062A \u0627\u0642\u062A\u0635\u0627\u062F\u06CC", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0647\u0633\u062A\u0647 \u0645\u0631\u06A9\u0632\u06CC \u06A9\u0631\u062C", "026", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0645\u06CC\u0631\u06A9\u0628\u06CC\u0631 \u06A9\u06CC\u0627\u0646\u0645\u0647\u0631"],
  [112, "\u062D\u0635\u0627\u0631\u06A9", "\u063A\u0631\u0628 \u06A9\u0631\u062C (\u0645\u0646\u0637\u0642\u0647 \u06F5 \u0648 \u06F6)", 35.838, 50.922, 52, 590, 8.2, 8.1, 8.2, 7.5, 7.8, 8.3, "\u0642\u0637\u0628 \u0639\u0644\u0645\u06CC \u0648 \u067E\u0698\u0648\u0647\u0634\u06CC \u0631\u0627\u0632\u06CC \u0648 \u062E\u0648\u0627\u0631\u0632\u0645\u06CC\u060C \u0628\u0648\u062F\u062C\u0647 \u0627\u0642\u062A\u0635\u0627\u062F\u06CC", "\u0628\u0627\u0641\u062A \u0642\u062F\u06CC\u0645\u06CC \u062F\u0631 \u0628\u0631\u062E\u06CC \u0641\u0631\u0639\u06CC\u200C\u0647\u0627", "026", "\u0628\u0644\u0648\u0627\u0631 \u0628\u0647\u0634\u062A\u06CC \u062D\u0635\u0627\u0631\u06A9"],
  [113, "\u0645\u0646\u0638\u0631\u06CC\u0647 \u06A9\u0631\u062C", "\u062C\u0646\u0648\u0628 \u06A9\u0631\u062C (\u0645\u0646\u0637\u0642\u0647 \u06F1\u06F0)", 35.729, 50.978, 54, 610, 8.1, 8.3, 8.4, 6.5, 8.2, 9, "\u0647\u0645\u062C\u0648\u0627\u0631\u06CC \u0628\u0627 \u0641\u0631\u062F\u06CC\u0633\u060C \u062F\u0633\u062A\u0631\u0633\u06CC \u062E\u0648\u0628 \u0648 \u0641\u0627\u06CC\u0644\u200C\u0647\u0627\u06CC \u0645\u062A\u0631\u0627\u0698 \u0645\u0646\u0627\u0633\u0628", "\u062A\u0631\u062F\u062F \u0628\u0627\u0644\u0627 \u062F\u0631 \u0628\u0644\u0648\u0627\u0631 \u0628\u0647\u0627\u0631\u0627\u0646", "026", "\u0641\u0644\u06A9\u0647 \u0627\u0648\u0644 \u0645\u0646\u0638\u0631\u06CC\u0647"],
  [114, "\u06AF\u0631\u0645\u062F\u0631\u0647", "\u0634\u0631\u0642 \u06A9\u0631\u062C (\u0645\u062D\u0648\u0631 \u0645\u062E\u0635\u0648\u0635 \u0648 \u0644\u0634\u06AF\u0631\u06CC)", 35.7675, 51.0595, 68, 780, 8.3, 8.4, 8.5, 8.8, 8.4, 8.8, "\u0627\u06CC\u0633\u062A\u06AF\u0627\u0647 \u0645\u062A\u0631\u0648 \u06AF\u0631\u0645\u062F\u0631\u0647\u060C \u0634\u0647\u0631\u06A9\u200C\u0647\u0627\u06CC \u0646\u0648\u0633\u0627\u0632 \u0633\u0639\u0627\u062F\u062A\u06CC\u0647 \u0648 \u0627\u0645\u06CC\u0631\u0622\u0628\u0627\u062F\u060C \u0646\u0632\u062F\u06CC\u06A9\u200C\u062A\u0631\u06CC\u0646 \u0646\u0642\u0637\u0647 \u0628\u0647 \u062A\u0647\u0631\u0627\u0646", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u0627\u062A\u0648\u0628\u0627\u0646 \u062F\u0631 \u0633\u0627\u0639\u062A \u067E\u06CC\u06A9 \u0635\u0628\u062D", "026", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0645\u06CC\u0631\u06A9\u0628\u06CC\u0631 \u06AF\u0631\u0645\u062F\u0631\u0647"],
  [115, "\u0645\u062D\u0645\u062F\u0634\u0647\u0631", "\u062C\u0646\u0648\u0628 \u06A9\u0631\u062C (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u06A9\u0631\u062C)", 35.759, 50.918, 56, 640, 8.8, 8.2, 8.3, 6.4, 8.3, 9.1, "\u0628\u0627\u063A\u0627\u062A \u0633\u0631\u0633\u0628\u0632\u060C \u0634\u0647\u0631\u06A9 \u0632\u06CC\u0628\u0627\u062F\u0634\u062A \u0648 \u0628\u0627\u0641\u062A \u0648\u06CC\u0644\u0627\u06CC\u06CC-\u0622\u067E\u0627\u0631\u062A\u0645\u0627\u0646\u06CC", "\u0641\u0627\u0635\u0644\u0647 \u0627\u0632 \u062E\u0637 \u0645\u062A\u0631\u0648 \u062F\u0631\u0648\u0646\u200C\u0634\u0647\u0631\u06CC", "026", "\u0628\u0644\u0648\u0627\u0631 \u062F\u0634\u062A \u0628\u0647\u0634\u062A \u0645\u062D\u0645\u062F\u0634\u0647\u0631"],
  [116, "\u0645\u0627\u0647\u062F\u0634\u062A", "\u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u06A9\u0631\u062C (\u0627\u0633\u062A\u0627\u0646 \u0627\u0644\u0628\u0631\u0632)", 35.726, 50.812, 44, 510, 8.9, 8, 8.1, 5.8, 8.1, 9.4, "\u0632\u0645\u06CC\u0646 \u06A9\u0627\u0645\u0644\u0627\u064B \u0645\u0633\u0637\u062D\u060C \u0628\u0627\u063A\u200C\u0648\u06CC\u0644\u0627\u0647\u0627 \u0648 \u0622\u067E\u0627\u0631\u062A\u0645\u0627\u0646\u200C\u0647\u0627\u06CC \u062E\u0648\u0634\u200C\u0642\u06CC\u0645\u062A", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0645\u0631\u06A9\u0632 \u06A9\u0631\u062C", "026", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0645\u0627\u0645 \u062E\u0645\u06CC\u0646\u06CC \u0645\u0627\u0647\u062F\u0634\u062A"],
  [117, "\u06A9\u0645\u0627\u0644\u0634\u0647\u0631", "\u063A\u0631\u0628 \u06A9\u0631\u062C (\u0627\u0633\u062A\u0627\u0646 \u0627\u0644\u0628\u0631\u0632)", 35.862, 50.8715, 50, 570, 8.4, 8.2, 8.3, 6.8, 8, 9, "\u0646\u0632\u062F\u06CC\u06A9\u06CC \u0628\u0647 \u0634\u0647\u0631\u06A9 \u0635\u0646\u0639\u062A\u06CC \u0628\u0647\u0627\u0631\u0633\u062A\u0627\u0646 \u0648 \u0628\u0632\u0631\u06AF\u0631\u0627\u0647 \u0642\u0632\u0648\u06CC\u0646", "\u062A\u0631\u062F\u062F \u062E\u0648\u062F\u0631\u0648\u0647\u0627\u06CC \u0633\u0646\u06AF\u06CC\u0646 \u062F\u0631 \u06A9\u0645\u0631\u0628\u0646\u062F\u06CC", "026", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0628\u0647\u0634\u062A\u06CC \u06A9\u0645\u0627\u0644\u0634\u0647\u0631"],
  [118, "\u0645\u0634\u06A9\u06CC\u0646\u200C\u062F\u0634\u062A", "\u062C\u0646\u0648\u0628 \u06A9\u0631\u062C (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0641\u0631\u062F\u06CC\u0633)", 35.721, 50.929, 48, 550, 8.7, 8.1, 8.2, 6, 8.2, 9.1, "\u0628\u0627\u063A\u200C\u0634\u0647\u0631 \u0622\u0631\u0627\u0645 \u0648 \u0642\u06CC\u0645\u062A \u0645\u0646\u0627\u0633\u0628 \u0628\u0631\u0627\u06CC \u062E\u0627\u0646\u0647\u200C\u0627\u0648\u0644\u06CC\u200C\u0647\u0627", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0627\u06CC\u0633\u062A\u06AF\u0627\u0647 \u0645\u062A\u0631\u0648", "026", "\u0628\u0644\u0648\u0627\u0631 \u0635\u06CC\u0627\u062F \u0634\u06CC\u0631\u0627\u0632\u06CC \u0645\u0634\u06A9\u06CC\u0646\u200C\u062F\u0634\u062A"],
  [119, "\u0647\u0634\u062A\u06AF\u0631\u062F (\u0633\u0627\u0648\u062C\u0628\u0644\u0627\u063A)", "\u063A\u0631\u0628 \u0627\u0633\u062A\u0627\u0646 \u0627\u0644\u0628\u0631\u0632 (\u0645\u0631\u06A9\u0632 \u0633\u0627\u0648\u062C\u0628\u0644\u0627\u063A)", 35.962, 50.68, 54, 610, 9.1, 8.5, 8.4, 8.2, 8.7, 8.9, "\u0645\u0631\u06A9\u0632 \u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0633\u0627\u0648\u062C\u0628\u0644\u0627\u063A\u060C \u0627\u06CC\u0633\u062A\u06AF\u0627\u0647 \u0645\u062A\u0631\u0648 \u0635\u0627\u062F\u0642\u06CC\u0647-\u0647\u0634\u062A\u06AF\u0631\u062F\u060C \u0627\u0645\u06A9\u0627\u0646\u0627\u062A \u06A9\u0627\u0645\u0644", "\u0641\u0627\u0635\u0644\u0647 \u06F3\u06F5 \u062F\u0642\u06CC\u0642\u0647\u200C\u0627\u06CC \u062A\u0627 \u06A9\u0631\u062C", "026", "\u0628\u0644\u0648\u0627\u0631 \u0622\u06CC\u062A\u200C\u0627\u0644\u0644\u0647 \u062E\u0627\u0645\u0646\u0647\u200C\u0627\u06CC \u0647\u0634\u062A\u06AF\u0631\u062F"],
  [120, "\u0634\u0647\u0631 \u062C\u062F\u06CC\u062F \u0645\u0647\u0633\u062A\u0627\u0646", "\u063A\u0631\u0628 \u0627\u0633\u062A\u0627\u0646 \u0627\u0644\u0628\u0631\u0632 (\u0647\u0634\u062A\u06AF\u0631\u062F \u062C\u062F\u06CC\u062F)", 35.991, 50.735, 38, 430, 9.3, 8.2, 8.3, 8.6, 8.4, 8.2, "\u0645\u062A\u0631\u0648 \u0645\u0633\u062A\u0642\u06CC\u0645 \u0628\u0647 \u062A\u0647\u0631\u0627\u0646 \u0648 \u06A9\u0631\u062C\u060C \u0634\u0647\u0631\u0633\u0627\u0632\u06CC \u0645\u062F\u0631\u0646 \u0648 \u0627\u0631\u0632\u0627\u0646\u200C\u062A\u0631\u06CC\u0646 \u0633\u0646\u062F\u062F\u0627\u0631 \u0645\u062A\u0631\u0648\u062E\u0648\u0631 \u0627\u0644\u0628\u0631\u0632", "\u062F\u0631 \u062D\u0627\u0644 \u062A\u06A9\u0645\u06CC\u0644 \u0645\u0631\u0627\u06A9\u0632 \u062A\u062C\u0627\u0631\u06CC \u0641\u0627\u0632\u0647\u0627\u06CC \u062C\u062F\u06CC\u062F", "026", "\u0641\u0627\u0632 \u06F1 \u0648 \u06F2 \u0634\u0647\u0631 \u062C\u062F\u06CC\u062F \u0645\u0647\u0633\u062A\u0627\u0646"],
  [121, "\u0686\u0647\u0627\u0631\u0628\u0627\u063A", "\u063A\u0631\u0628 \u06A9\u0631\u062C (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0686\u0647\u0627\u0631\u0628\u0627\u063A)", 35.829, 50.845, 52, 590, 9, 8.1, 8.2, 7.2, 8.3, 9.3, "\u0642\u0637\u0628 \u0628\u0627\u063A\u200C\u0648\u06CC\u0644\u0627 \u0648 \u0634\u0647\u0631\u06A9\u200C\u0647\u0627\u06CC \u0645\u0633\u06A9\u0648\u0646\u06CC \u0633\u0631\u0633\u0628\u0632 \u0628\u06CC\u0646 \u06A9\u0631\u062C \u0648 \u0647\u0634\u062A\u06AF\u0631\u062F", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u062A\u0639\u0637\u06CC\u0644\u0627\u062A \u0622\u062E\u0631 \u0647\u0641\u062A\u0647", "026", "\u0628\u0644\u0648\u0627\u0631 \u0686\u0647\u0627\u0631\u0628\u0627\u063A"],
  [122, "\u06A9\u0631\u062F\u0627\u0646", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0627\u0644\u0628\u0631\u0632 (\u0633\u0627\u0648\u062C\u0628\u0644\u0627\u063A)", 35.986, 50.829, 95, 1100, 9.6, 8.4, 8.3, 5.5, 8.9, 7.5, "\u0642\u0637\u0628 \u0627\u0648\u0644 \u0648\u06CC\u0644\u0627\u0633\u0627\u0632\u06CC \u0644\u0648\u06A9\u0633 \u0627\u0644\u0628\u0631\u0632\u060C \u0631\u0648\u062F\u062E\u0627\u0646\u0647 \u0648 \u0622\u0628\u200C\u0648\u0647\u0648\u0627\u06CC \u06A9\u0648\u0647\u0633\u062A\u0627\u0646\u06CC \u0645\u0645\u062A\u0627\u0632", "\u0642\u06CC\u0645\u062A \u0628\u0627\u0644\u0627\u06CC \u0632\u0645\u06CC\u0646 \u0648 \u062A\u0631\u0627\u0641\u06CC\u06A9 \u062C\u0645\u0639\u0647\u200C\u0647\u0627", "026", "\u0628\u0644\u0648\u0627\u0631 \u0634\u0647\u062F\u0627\u06CC \u06A9\u0631\u062F\u0627\u0646"],
  [123, "\u06A9\u0648\u0647\u0633\u0627\u0631", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0627\u0644\u0628\u0631\u0632 (\u0686\u0646\u062F\u0627\u0631)", 35.998, 50.785, 72, 820, 9.5, 8.3, 8.2, 5.8, 8.8, 7.6, "\u0627\u0642\u0644\u06CC\u0645 \u06A9\u0648\u0647\u0633\u062A\u0627\u0646\u06CC \u062E\u0646\u06A9 \u0648 \u0634\u0647\u0631\u06A9\u200C\u0647\u0627\u06CC \u0648\u06CC\u0644\u0627\u06CC\u06CC \u0648 \u0622\u067E\u0627\u0631\u062A\u0645\u0627\u0646\u06CC \u062F\u0646\u062C", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0645\u0631\u0627\u06A9\u0632 \u0627\u062F\u0627\u0631\u06CC \u06A9\u0631\u062C", "026", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0635\u0644\u06CC \u06A9\u0648\u0647\u0633\u0627\u0631"],
  [124, "\u0646\u0638\u0631\u0622\u0628\u0627\u062F", "\u063A\u0631\u0628 \u0627\u0633\u062A\u0627\u0646 \u0627\u0644\u0628\u0631\u0632 (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0646\u0638\u0631\u0622\u0628\u0627\u062F)", 35.954, 50.607, 40, 460, 8.9, 8.3, 8.2, 6.2, 8.4, 9.4, "\u0646\u0632\u062F\u06CC\u06A9\u06CC \u0628\u0647 \u0634\u0647\u0631\u06A9 \u0635\u0646\u0639\u062A\u06CC \u0633\u067E\u0647\u0631 \u0648 \u0642\u06CC\u0645\u062A \u0628\u0633\u06CC\u0627\u0631 \u0627\u0642\u062A\u0635\u0627\u062F\u06CC \u0645\u0633\u06A9\u0646", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0645\u0631\u06A9\u0632 \u0627\u0633\u062A\u0627\u0646", "026", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0627\u0644\u063A\u062F\u06CC\u0631 \u0646\u0638\u0631\u0622\u0628\u0627\u062F"],
  [125, "\u0637\u0627\u0644\u0642\u0627\u0646", "\u0634\u0645\u0627\u0644 \u0627\u0633\u062A\u0627\u0646 \u0627\u0644\u0628\u0631\u0632 (\u06CC\u06CC\u0644\u0627\u0642 \u0637\u0627\u0644\u0642\u0627\u0646)", 36.177, 50.765, 68, 760, 9.9, 8.5, 8, 4.5, 9.5, 6, "\u067E\u0627\u06A9\u200C\u062A\u0631\u06CC\u0646 \u0647\u0648\u0627\u06CC \u0627\u0633\u062A\u0627\u0646 \u0627\u0644\u0628\u0631\u0632\u060C \u062F\u0631\u06CC\u0627\u0686\u0647 \u0633\u062F \u0637\u0627\u0644\u0642\u0627\u0646 \u0648 \u0627\u0645\u0646\u06CC\u062A \u0628\u06CC\u200C\u0646\u0638\u06CC\u0631", "\u0645\u0633\u06CC\u0631 \u06A9\u0648\u0647\u0633\u062A\u0627\u0646\u06CC \u0648 \u0633\u0631\u062F\u0633\u06CC\u0631 \u062F\u0631 \u0632\u0645\u0633\u062A\u0627\u0646", "026", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0635\u0644\u06CC \u0634\u0647\u0631\u06A9 \u0637\u0627\u0644\u0642\u0627\u0646"]
];
var MASHHAD_SEEDS = [
  [207, "\u0647\u0627\u0634\u0645\u06CC\u0647", "\u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u0645\u0634\u0647\u062F (\u0645\u0646\u0637\u0642\u0647 \u06F9)", 36.308, 59.512, 125, 1450, 9.2, 9.1, 9, 8.2, 9.3, 7.8, "\u0628\u0631\u062C\u200C\u0647\u0627\u06CC \u0644\u0648\u06A9\u0633 \u06A9\u0648\u0647\u0633\u0631 \u0648 \u0647\u0627\u0634\u0645\u06CC\u0647\u060C \u0647\u0648\u0627\u06CC \u067E\u0627\u06A9 \u06A9\u0648\u0647\u067E\u0627\u06CC\u0647 \u0648 \u067E\u0631\u0633\u062A\u06CC\u0698 \u0639\u0627\u0644\u06CC", "\u0634\u06CC\u0628 \u062F\u0631 \u0627\u0646\u062A\u0647\u0627\u06CC \u062C\u0646\u0648\u0628\u06CC \u0628\u0644\u0648\u0627\u0631 \u0647\u0627\u0634\u0645\u06CC\u0647", "051", "\u0628\u0644\u0648\u0627\u0631 \u0647\u0627\u0634\u0645\u06CC\u0647"],
  [208, "\u0631\u0636\u0627\u0634\u0647\u0631", "\u062C\u0646\u0648\u0628 \u0645\u0634\u0647\u062F (\u0645\u0646\u0637\u0642\u0647 \u06F9)", 36.286, 59.542, 88, 1020, 8.6, 8.9, 8.9, 8.8, 8.9, 8.8, "\u062E\u06CC\u0627\u0628\u0627\u0646\u200C\u0647\u0627\u06CC \u0639\u0631\u06CC\u0636 \u067E\u06CC\u0631\u0648\u0632\u06CC \u0648 \u062E\u0627\u0642\u0627\u0646\u06CC\u060C \u062F\u0633\u062A\u0631\u0633\u06CC \u0628\u0647 \u0645\u062A\u0631\u0648 \u062E\u0637 \u06F1 \u0648 \u06F2", "\u062A\u0631\u062F\u062F \u0628\u0627\u0644\u0627 \u062F\u0631 \u0645\u06CC\u062F\u0627\u0646 \u0633\u0644\u0645\u0627\u0646 \u0641\u0627\u0631\u0633\u06CC", "051", "\u0628\u0644\u0648\u0627\u0631 \u067E\u06CC\u0631\u0648\u0632\u06CC \u0648 \u062E\u0627\u0642\u0627\u0646\u06CC"],
  [209, "\u0641\u0631\u0627\u0645\u0631\u0632 \u0639\u0628\u0627\u0633\u06CC", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0645\u0631\u06A9\u0632 \u0645\u0634\u0647\u062F (\u0645\u0646\u0637\u0642\u0647 \u06F1)", 36.334, 59.556, 96, 1120, 8.5, 9, 9.1, 7.8, 9, 9.2, "\u062E\u06CC\u0627\u0628\u0627\u0646\u200C\u0628\u0646\u062F\u06CC \u0634\u0637\u0631\u0646\u062C\u06CC \u0639\u0627\u0644\u06CC\u060C \u0645\u0631\u0627\u06A9\u0632 \u062E\u0631\u06CC\u062F \u0641\u0631\u062F\u0648\u0633\u06CC \u0648 \u062C\u0627\u0646\u0628\u0627\u0632", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u0633\u0627\u0639\u0627\u062A \u062E\u0631\u06CC\u062F \u062F\u0631 \u0628\u0644\u0648\u0627\u0631 \u0641\u0631\u062F\u0648\u0633\u06CC", "051", "\u0628\u0644\u0648\u0627\u0631 \u0641\u0631\u0627\u0645\u0631\u0632 \u0639\u0628\u0627\u0633\u06CC"],
  [210, "\u0633\u0646\u0627\u0628\u0627\u062F \u0648 \u0622\u0628\u06A9\u0648\u0647", "\u0645\u0631\u06A9\u0632 \u0645\u0634\u0647\u062F (\u0645\u0646\u0637\u0642\u0647 \u06F1)", 36.304, 59.582, 102, 1180, 8.1, 9.2, 9.1, 9, 9.1, 9.1, "\u0627\u0635\u0627\u0644\u062A \u0628\u0627\u0644\u0627\u06CC \u0634\u0647\u0631\u06CC\u060C \u062F\u0633\u062A\u0631\u0633\u06CC \u0633\u0631\u06CC\u0639 \u0628\u0647 \u0627\u062D\u0645\u062F\u0622\u0628\u0627\u062F \u0648 \u0645\u0631\u0627\u06A9\u0632 \u0627\u062F\u0627\u0631\u06CC", "\u06A9\u0645\u06CC\u0627\u0628\u06CC \u0632\u0645\u06CC\u0646 \u0646\u0648\u0633\u0627\u0632 \u062F\u0631 \u0628\u0627\u0641\u062A \u0642\u062F\u06CC\u0645", "051", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0633\u0646\u0627\u0628\u0627\u062F \u0648 \u0641\u0644\u0633\u0637\u06CC\u0646"],
  [211, "\u0622\u0632\u0627\u062F\u0634\u0647\u0631 \u0648 \u0645\u0639\u0644\u0645", "\u063A\u0631\u0628 \u0645\u0634\u0647\u062F (\u0645\u0646\u0637\u0642\u0647 \u06F1\u06F1)", 36.339, 59.524, 92, 1060, 8.7, 8.9, 9, 8.8, 8.9, 9.1, "\u0645\u0631\u0627\u06A9\u0632 \u062A\u062C\u0627\u0631\u06CC \u0628\u0644\u0648\u0627\u0631 \u0627\u0645\u0627\u0645\u062A \u0648 \u0645\u0639\u0644\u0645\u060C \u062F\u0633\u062A\u0631\u0633\u06CC \u0639\u0627\u0644\u06CC \u0628\u0647 \u067E\u0627\u0631\u06A9 \u0645\u0644\u062A \u0648 \u0645\u062A\u0631\u0648", "\u0634\u0644\u0648\u063A\u06CC \u0639\u0635\u0631\u06AF\u0627\u0647\u06CC \u0628\u0644\u0648\u0627\u0631 \u0627\u0645\u0627\u0645\u062A", "051", "\u0628\u0644\u0648\u0627\u0631 \u0645\u0639\u0644\u0645 \u0648 \u0627\u0645\u0627\u0645\u062A"],
  [212, "\u0633\u06CC\u062F\u0631\u0636\u06CC \u0648 \u062F\u0627\u0646\u0634\u062C\u0648", "\u063A\u0631\u0628 \u0645\u0634\u0647\u062F (\u0645\u0646\u0637\u0642\u0647 \u06F1\u06F1)", 36.341, 59.506, 90, 1040, 8.8, 8.9, 9, 9.2, 9, 9, "\u0628\u0627\u0641\u062A \u0641\u0631\u0647\u0646\u06AF\u06CC \u0648 \u062F\u0627\u0646\u0634\u06AF\u0627\u0647\u06CC\u060C \u062F\u0633\u062A\u0631\u0633\u06CC \u0645\u0633\u062A\u0642\u06CC\u0645 \u0628\u0647 \u0645\u062A\u0631\u0648 \u0633\u06CC\u062F\u0631\u0636\u06CC \u0648 \u062F\u0627\u0646\u0634\u062C\u0648", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u062A\u0642\u0627\u0637\u0639 \u0628\u0644\u0648\u0627\u0631 \u0641\u0631\u0647\u0646\u06AF", "051", "\u0628\u0644\u0648\u0627\u0631 \u0633\u06CC\u062F\u0631\u0636\u06CC \u0648 \u062F\u0627\u0646\u0634\u062C\u0648"],
  [213, "\u06A9\u0648\u062B\u0631", "\u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u0645\u0634\u0647\u062F (\u0645\u0646\u0637\u0642\u0647 \u06F9)", 36.319, 59.528, 110, 1280, 8.9, 9, 9.1, 8.6, 9.2, 8.9, "\u0646\u0648\u0633\u0627\u0632\u060C \u062F\u0646\u062C \u0648 \u0627\u0639\u06CC\u0627\u0646\u06CC \u0628\u06CC\u0646 \u0648\u06A9\u06CC\u0644\u200C\u0622\u0628\u0627\u062F \u0648 \u067E\u06CC\u0631\u0648\u0632\u06CC\u060C \u0646\u0632\u062F\u06CC\u06A9 \u0645\u062A\u0631\u0648 \u06A9\u0648\u062B\u0631", "\u0642\u06CC\u0645\u062A \u0628\u0627\u0644\u0627\u062A\u0631 \u0627\u0632 \u0645\u06CC\u0627\u0646\u06AF\u06CC\u0646 \u0645\u0646\u0637\u0642\u0647 \u06F9", "051", "\u0628\u0644\u0648\u0627\u0631 \u06A9\u0648\u062B\u0631 \u0634\u0645\u0627\u0644\u06CC"],
  [214, "\u0647\u0646\u0631\u0633\u062A\u0627\u0646 \u0648 \u0647\u0641\u062A\u200C\u062A\u06CC\u0631", "\u063A\u0631\u0628 \u0645\u0634\u0647\u062F (\u0645\u0646\u0637\u0642\u0647 \u06F9)", 36.325, 59.502, 105, 1220, 9, 9, 9, 8.8, 9.1, 8.6, "\u0628\u0631\u062C\u200C\u0622\u067E\u0627\u0631\u062A\u0645\u0627\u0646\u200C\u0647\u0627\u06CC \u0645\u062F\u0631\u0646\u060C \u06A9\u0627\u0641\u0647\u200C\u0647\u0627 \u0648 \u0645\u0631\u0627\u06A9\u0632 \u062E\u0631\u06CC\u062F \u0647\u0641\u062A\u200C\u062A\u06CC\u0631", "\u0634\u0644\u0648\u063A\u06CC \u0634\u0628\u200C\u0647\u0627\u06CC \u062A\u0639\u0637\u06CC\u0644 \u062F\u0631 \u0645\u062D\u0648\u0631 \u0647\u0641\u062A\u200C\u062A\u06CC\u0631", "051", "\u0628\u0644\u0648\u0627\u0631 \u0647\u0641\u062A\u200C\u062A\u06CC\u0631 \u0648 \u0647\u0646\u0631\u0633\u062A\u0627\u0646"],
  [215, "\u0641\u0631\u0647\u0627\u062F \u0648 \u0645\u0644\u06A9\u200C\u0622\u0628\u0627\u062F", "\u0645\u0631\u06A9\u0632 \u0627\u0639\u06CC\u0627\u0646\u06CC \u0645\u0634\u0647\u062F (\u0645\u0646\u0637\u0642\u0647 \u06F1)", 36.306, 59.561, 148, 1720, 9.1, 9.4, 9.2, 8.9, 9.6, 9.2, "\u0647\u0645\u062C\u0648\u0627\u0631\u06CC \u0628\u0627 \u0628\u0627\u063A \u0645\u0644\u06A9\u200C\u0622\u0628\u0627\u062F (\u0631\u06CC\u0647 \u062A\u0646\u0641\u0633\u06CC \u0645\u0634\u0647\u062F)\u060C \u0644\u0648\u06A9\u0633\u200C\u062A\u0631\u06CC\u0646 \u0645\u062D\u0644\u0647 \u0648\u06CC\u0644\u0627\u06CC\u06CC-\u0622\u067E\u0627\u0631\u062A\u0645\u0627\u0646\u06CC", "\u0628\u0627\u0644\u0627\u062A\u0631\u06CC\u0646 \u0633\u0637\u062D \u0642\u06CC\u0645\u062A \u062F\u0631 \u0645\u0634\u0647\u062F", "051", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0641\u0631\u0647\u0627\u062F \u0648 \u0646\u0633\u062A\u0631\u0646"],
  [216, "\u0637\u0628\u0631\u0633\u06CC \u0648 \u062D\u0631\u0645 \u0645\u0637\u0647\u0631", "\u0634\u0645\u0627\u0644 \u0634\u0631\u0642 \u0645\u0631\u06A9\u0632 \u0645\u0634\u0647\u062F (\u0645\u0646\u0637\u0642\u0647 \u06F3 \u0648 \u062B\u0627\u0645\u0646)", 36.298, 59.622, 58, 670, 7.6, 8.5, 8.4, 9.4, 8.2, 9, "\u0647\u0645\u062C\u0648\u0627\u0631\u06CC \u0645\u0633\u062A\u0642\u06CC\u0645 \u0628\u0627 \u062D\u0631\u0645 \u0645\u0637\u0647\u0631 \u0631\u0636\u0648\u06CC \u0648 \u062E\u0637 \u06F2 \u0642\u0637\u0627\u0631 \u0634\u0647\u0631\u06CC", "\u062A\u0631\u0627\u06A9\u0645 \u0628\u0627\u0644\u0627\u06CC \u0632\u0627\u0626\u0631\u0627\u0646 \u062F\u0631 \u0627\u06CC\u0627\u0645 \u0645\u0646\u0627\u0633\u0628\u062A\u06CC", "051", "\u0628\u0644\u0648\u0627\u0631 \u0637\u0628\u0631\u0633\u06CC \u062C\u0646\u0648\u0628\u06CC"],
  [217, "\u0634\u0647\u0631 \u062C\u062F\u06CC\u062F \u06AF\u0644\u0628\u0647\u0627\u0631", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0645\u0634\u0647\u062F (\u0645\u062D\u0648\u0631 \u0686\u0646\u0627\u0631\u0627\u0646)", 36.565, 59.222, 34, 390, 9.2, 8.2, 8.3, 6.8, 8.3, 9.4, "\u0634\u0647\u0631 \u062C\u062F\u06CC\u062F \u062F\u0627\u0646\u0634\u06AF\u0627\u0647\u06CC \u0648 \u0645\u0633\u06A9\u0648\u0646\u06CC \u0628\u0627 \u0642\u06CC\u0645\u062A \u0628\u0633\u06CC\u0627\u0631 \u0645\u0646\u0627\u0633\u0628 \u0648 \u0628\u0644\u0648\u0627\u0631\u0647\u0627\u06CC \u0639\u0631\u06CC\u0636", "\u0641\u0627\u0635\u0644\u0647 \u06F3\u06F5 \u06A9\u06CC\u0644\u0648\u0645\u062A\u0631\u06CC \u062A\u0627 \u0645\u0634\u0647\u062F", "051", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0633\u062A\u0642\u0644\u0627\u0644 \u06AF\u0644\u0628\u0647\u0627\u0631"],
  [218, "\u0634\u0647\u0631 \u062C\u062F\u06CC\u062F \u0628\u06CC\u0646\u0627\u0644\u0648\u062F", "\u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u0645\u0634\u0647\u062F (\u0645\u062D\u0648\u0631 \u0646\u06CC\u0634\u0627\u0628\u0648\u0631)", 36.192, 59.195, 32, 360, 9.4, 8, 8.1, 5.8, 8.4, 8.5, "\u0647\u0648\u0627\u06CC \u067E\u0627\u06A9 \u062F\u0627\u0645\u0646\u0647 \u0628\u06CC\u0646\u0627\u0644\u0648\u062F \u0648 \u0627\u0631\u0632\u0627\u0646\u200C\u062A\u0631\u06CC\u0646 \u0622\u067E\u0627\u0631\u062A\u0645\u0627\u0646\u200C\u0647\u0627\u06CC \u0646\u0648\u0633\u0627\u0632 \u062D\u0648\u0645\u0647 \u0645\u0634\u0647\u062F", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0645\u0631\u06A9\u0632 \u0634\u0647\u0631 \u0645\u0634\u0647\u062F", "051", "\u0628\u0644\u0648\u0627\u0631 \u0645\u0637\u0647\u0631\u06CC \u0628\u06CC\u0646\u0627\u0644\u0648\u062F"],
  [219, "\u0637\u0631\u0642\u0628\u0647", "\u063A\u0631\u0628 \u0645\u0634\u0647\u062F (\u06CC\u06CC\u0644\u0627\u0642 \u0637\u0631\u0642\u0628\u0647)", 36.31, 59.373, 86, 980, 9.7, 8.6, 8.5, 6.5, 9.2, 6.8, "\u0627\u0642\u0644\u06CC\u0645 \u06A9\u0648\u0647\u0633\u062A\u0627\u0646\u06CC \u0648 \u0628\u0627\u063A\u0627\u062A \u06CC\u06CC\u0644\u0627\u0642\u06CC\u060C \u0648\u06CC\u0644\u0627\u0647\u0627 \u0648 \u0645\u062C\u062A\u0645\u0639\u200C\u0647\u0627\u06CC \u0644\u0648\u06A9\u0633 \u062E\u0648\u0634\u200C\u0622\u0628\u200C\u0648\u0647\u0648\u0627", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u06AF\u0631\u062F\u0634\u06AF\u0631\u06CC \u062F\u0631 \u0631\u0648\u0632\u0647\u0627\u06CC \u062A\u0639\u0637\u06CC\u0644", "051", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0645\u0627\u0645 \u0631\u0636\u0627 \u0637\u0631\u0642\u0628\u0647"],
  [220, "\u0634\u0627\u0646\u062F\u06CC\u0632", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0645\u0634\u0647\u062F (\u06CC\u06CC\u0644\u0627\u0642 \u0634\u0627\u0646\u062F\u06CC\u0632)", 36.395, 59.293, 84, 950, 9.7, 8.5, 8.4, 6, 9.2, 7.4, "\u0642\u0637\u0628 \u06AF\u0631\u062F\u0634\u06AF\u0631\u06CC \u0628\u06CC\u0646\u200C\u0627\u0644\u0645\u0644\u0644\u06CC \u0648 \u0628\u0627\u063A\u200C\u0648\u06CC\u0644\u0627\u0647\u0627\u06CC \u0645\u0645\u062A\u0627\u0632 \u0645\u0634\u0647\u062F", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u0639\u0635\u0631\u0647\u0627\u06CC \u067E\u0646\u062C\u0634\u0646\u0628\u0647 \u0648 \u062C\u0645\u0639\u0647", "051", "\u0628\u0644\u0648\u0627\u0631 \u0648\u0644\u06CC\u0639\u0635\u0631 \u0634\u0627\u0646\u062F\u06CC\u0632"],
  [221, "\u0646\u06CC\u0634\u0627\u0628\u0648\u0631 (\u0628\u0644\u0648\u0627\u0631 \u0628\u0639\u062B\u062A)", "\u062E\u0631\u0627\u0633\u0627\u0646 \u0631\u0636\u0648\u06CC (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0646\u06CC\u0634\u0627\u0628\u0648\u0631)", 36.214, 58.796, 52, 590, 9, 8.6, 8.5, 6.5, 8.9, 9.2, "\u062F\u0648\u0645\u06CC\u0646 \u0634\u0647\u0631 \u0628\u0632\u0631\u06AF \u062E\u0631\u0627\u0633\u0627\u0646 \u0631\u0636\u0648\u06CC\u060C \u067E\u0627\u06CC\u062A\u062E\u062A \u0641\u0631\u0647\u0646\u06AF \u0648 \u062A\u0645\u062F\u0646 \u062E\u06CC\u0627\u0645 \u0648 \u0639\u0637\u0627\u0631", "\u0641\u0627\u0635\u0644\u0647 \u06F1\u06F1\u06F0 \u06A9\u06CC\u0644\u0648\u0645\u062A\u0631\u06CC \u062A\u0627 \u0645\u0634\u0647\u062F", "051", "\u0628\u0644\u0648\u0627\u0631 \u0628\u0639\u062B\u062A \u0648 \u0645\u0644\u0627\u0635\u062F\u0631\u0627 \u0646\u06CC\u0634\u0627\u0628\u0648\u0631"],
  [222, "\u0633\u0628\u0632\u0648\u0627\u0631 (\u062A\u0648\u062D\u06CC\u062F\u0634\u0647\u0631)", "\u063A\u0631\u0628 \u062E\u0631\u0627\u0633\u0627\u0646 \u0631\u0636\u0648\u06CC (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0633\u0628\u0632\u0648\u0627\u0631)", 36.2125, 57.6819, 48, 540, 8.6, 8.5, 8.5, 6.2, 8.8, 9.4, "\u0642\u0637\u0628 \u062F\u0627\u0646\u0634\u06AF\u0627\u0647\u06CC\u060C \u067E\u0632\u0634\u06A9\u06CC \u0648 \u062A\u062C\u0627\u0631\u06CC \u063A\u0631\u0628 \u062E\u0631\u0627\u0633\u0627\u0646\u060C \u0634\u0647\u0631\u0633\u0627\u0632\u06CC \u0645\u0646\u0638\u0645 \u062A\u0648\u062D\u06CC\u062F\u0634\u0647\u0631", "\u0627\u0642\u0644\u06CC\u0645 \u06AF\u0631\u0645\u200C\u062A\u0631 \u062F\u0631 \u062A\u0627\u0628\u0633\u062A\u0627\u0646", "051", "\u0628\u0644\u0648\u0627\u0631 \u062A\u0648\u062D\u06CC\u062F\u0634\u0647\u0631 \u0633\u0628\u0632\u0648\u0627\u0631"],
  [223, "\u062A\u0631\u0628\u062A \u062D\u06CC\u062F\u0631\u06CC\u0647 (\u0648\u0644\u06CC\u0639\u0635\u0631)", "\u0645\u0631\u06A9\u0632 \u062E\u0631\u0627\u0633\u0627\u0646 \u0631\u0636\u0648\u06CC (\u062A\u0631\u0628\u062A \u062D\u06CC\u062F\u0631\u06CC\u0647)", 35.274, 59.2195, 44, 500, 8.9, 8.4, 8.4, 6, 8.8, 8.9, "\u067E\u0627\u06CC\u062A\u062E\u062A \u0632\u0639\u0641\u0631\u0627\u0646 \u062C\u0647\u0627\u0646 \u0648 \u0634\u0627\u0647\u0631\u0627\u0647 \u0627\u0631\u062A\u0628\u0627\u0637\u06CC \u062C\u0646\u0648\u0628 \u062E\u0631\u0627\u0633\u0627\u0646", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0645\u0631\u06A9\u0632 \u0627\u0633\u062A\u0627\u0646", "051", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0648\u0644\u06CC\u0639\u0635\u0631 \u0648 \u0641\u0631\u062F\u0648\u0633\u06CC"],
  [224, "\u0642\u0648\u0686\u0627\u0646 (\u062E\u06CC\u0627\u0628\u0627\u0646 \u0627\u0645\u0627\u0645)", "\u0634\u0645\u0627\u0644 \u062E\u0631\u0627\u0633\u0627\u0646 \u0631\u0636\u0648\u06CC (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0642\u0648\u0686\u0627\u0646)", 37.106, 58.5095, 38, 430, 9.2, 8.3, 8.2, 5.8, 8.7, 8.8, "\u0622\u0628\u200C\u0648\u0647\u0648\u0627\u06CC \u062E\u0646\u06A9 \u06A9\u0648\u0647\u0633\u062A\u0627\u0646\u06CC \u0648 \u0642\u06CC\u0645\u062A \u0628\u0633\u06CC\u0627\u0631 \u0645\u0646\u0627\u0633\u0628 \u062E\u0631\u06CC\u062F \u0645\u0633\u06A9\u0646", "\u0632\u0645\u0633\u062A\u0627\u0646\u200C\u0647\u0627\u06CC \u0633\u0631\u062F\u0633\u06CC\u0631", "051", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0627\u0645\u0627\u0645 \u062E\u0645\u06CC\u0646\u06CC \u0642\u0648\u0686\u0627\u0646"],
  [225, "\u06A9\u0627\u0634\u0645\u0631 (\u0628\u0644\u0648\u0627\u0631 \u0633\u06CC\u062F\u0645\u0631\u062A\u0636\u06CC)", "\u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u062E\u0631\u0627\u0633\u0627\u0646 \u0631\u0636\u0648\u06CC (\u06A9\u0627\u0634\u0645\u0631)", 35.238, 58.4655, 42, 480, 8.9, 8.4, 8.3, 5.8, 8.9, 9, "\u0634\u0647\u0631 \u0632\u06CC\u0627\u0631\u062A\u06CC \u0648 \u0628\u0627\u063A\u200C\u0634\u0647\u0631 \u0633\u0631\u0633\u0628\u0632 \u0628\u0627 \u0628\u0644\u0648\u0627\u0631 \u0645\u0634\u062C\u0631 \u0633\u06CC\u062F\u0645\u0631\u062A\u0636\u06CC", "\u0641\u0627\u0635\u0644\u0647 \u0627\u0632 \u0645\u0631\u06A9\u0632 \u0627\u0633\u062A\u0627\u0646", "051", "\u0628\u0644\u0648\u0627\u0631 \u0633\u06CC\u062F\u0645\u0631\u062A\u0636\u06CC \u06A9\u0627\u0634\u0645\u0631"]
];
var ISFAHAN_SEEDS = [
  [307, "\u0686\u0647\u0627\u0631\u0628\u0627\u063A \u0628\u0627\u0644\u0627 \u0648 \u0646\u0638\u0631", "\u062C\u0646\u0648\u0628 \u0645\u0631\u06A9\u0632 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0645\u0646\u0637\u0642\u0647 \u06F5 \u0648 \u06F6)", 32.631, 51.6655, 136, 1560, 8.5, 9.2, 9.1, 9.5, 9.4, 9.3, "\u0627\u0635\u06CC\u0644\u200C\u062A\u0631\u06CC\u0646 \u0645\u062D\u0648\u0631 \u062A\u062C\u0627\u0631\u06CC \u0648 \u0645\u0633\u06A9\u0648\u0646\u06CC \u0627\u0635\u0641\u0647\u0627\u0646\u060C \u0627\u06CC\u0633\u062A\u06AF\u0627\u0647\u200C\u0647\u0627\u06CC \u0645\u062A\u0631\u0648 \u0634\u0631\u06CC\u0639\u062A\u06CC \u0648 \u0633\u06CC\u200C\u0648\u0633\u0647\u200C\u067E\u0644", "\u0634\u0644\u0648\u063A\u06CC \u0633\u0627\u0639\u0627\u062A \u0639\u0635\u0631\u06AF\u0627\u0647\u06CC", "031", "\u0686\u0647\u0627\u0631\u0628\u0627\u063A \u0628\u0627\u0644\u0627"],
  [308, "\u0645\u0634\u062A\u0627\u0642 \u0648 \u0622\u0628\u0634\u0627\u0631", "\u062D\u0627\u0634\u06CC\u0647 \u0632\u0627\u06CC\u0646\u062F\u0647\u200C\u0631\u0648\u062F (\u0645\u0646\u0637\u0642\u0647 \u06F3 \u0648 \u06F4)", 32.6345, 51.698, 128, 1460, 9, 9.1, 8.9, 7.6, 9.3, 9.4, "\u0686\u0634\u0645\u200C\u0627\u0646\u062F\u0627\u0632 \u0645\u0633\u062A\u0642\u06CC\u0645 \u067E\u0627\u0631\u06A9 \u0633\u0627\u062D\u0644\u06CC \u0632\u0627\u06CC\u0646\u062F\u0647\u200C\u0631\u0648\u062F \u0648 \u067E\u0644 \u062E\u0648\u0627\u062C\u0648\u060C \u0647\u0648\u0627\u06CC \u0645\u0637\u0628\u0648\u0639", "\u0642\u06CC\u0645\u062A \u0628\u0627\u0644\u0627\u06CC \u067E\u0644\u0627\u06A9\u200C\u0647\u0627\u06CC \u0627\u0648\u0644 \u0631\u0648\u062F\u062E\u0627\u0646\u0647", "031", "\u0628\u0644\u0648\u0627\u0631 \u0645\u0634\u062A\u0627\u0642 \u0627\u0648\u0644 \u0648 \u062F\u0648\u0645"],
  [309, "\u0645\u0647\u0631\u0622\u0628\u0627\u062F \u0648 \u0628\u0632\u0631\u06AF\u0645\u0647\u0631", "\u0634\u0631\u0642 \u0645\u0631\u06A9\u0632 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0645\u0646\u0637\u0642\u0647 \u06F4)", 32.642, 51.706, 114, 1300, 8.7, 9, 8.9, 7.8, 9.2, 9.3, "\u0645\u062D\u0644\u0647 \u0646\u0648\u0633\u0627\u0632 \u0648 \u0627\u0639\u06CC\u0627\u0646\u06CC \u0634\u0631\u0642 \u0627\u0635\u0641\u0647\u0627\u0646 \u0628\u0627 \u0628\u0631\u062C\u200C\u0647\u0627 \u0648 \u0645\u062C\u062A\u0645\u0639\u200C\u0647\u0627\u06CC \u0645\u062F\u0631\u0646", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u0645\u06CC\u062F\u0627\u0646 \u0628\u0632\u0631\u06AF\u0645\u0647\u0631 \u062F\u0631 \u0633\u0627\u0639\u062A \u0627\u0648\u062C", "031", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0645\u0647\u0631\u0622\u0628\u0627\u062F \u0648 \u0644\u0627\u0647\u0648\u0631"],
  [310, "\u0627\u0645\u06CC\u0631\u062D\u0645\u0632\u0647 \u0648 \u062D\u06A9\u06CC\u0645 \u0646\u0638\u0627\u0645\u06CC", "\u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0645\u0646\u0637\u0642\u0647 \u06F5)", 32.628, 51.648, 118, 1350, 8.6, 9, 8.9, 8, 9.2, 9.2, "\u0627\u0635\u0627\u0644\u062A \u0628\u0627\u0644\u0627\u060C \u062F\u0633\u062A\u0631\u0633\u06CC \u0639\u0627\u0644\u06CC \u0628\u0647 \u0635\u0641\u0647\u060C \u062C\u0644\u0641\u0627 \u0648 \u0645\u0631\u0627\u06A9\u0632 \u062F\u0631\u0645\u0627\u0646\u06CC", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u0686\u0647\u0627\u0631\u0631\u0627\u0647 \u062D\u06A9\u06CC\u0645 \u0646\u0638\u0627\u0645\u06CC", "031", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u062D\u06A9\u06CC\u0645 \u0646\u0638\u0627\u0645\u06CC"],
  [311, "\u0645\u0644\u06A9\u200C\u0634\u0647\u0631 \u0648 \u0645\u0637\u0647\u0631\u06CC", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0645\u0646\u0637\u0642\u0647 \u06F1\u06F2)", 32.725, 51.662, 74, 840, 8.5, 8.7, 8.8, 9, 8.6, 9.4, "\u0627\u06CC\u0633\u062A\u06AF\u0627\u0647 \u0645\u062A\u0631\u0648 \u0645\u0641\u062A\u062D \u0648 \u0645\u0637\u0647\u0631\u06CC\u060C \u0645\u0631\u0627\u06A9\u0632 \u062E\u0631\u06CC\u062F \u06A9\u0627\u0645\u0644 \u0648 \u0646\u0642\u062F\u0634\u0648\u0646\u062F\u06AF\u06CC \u0628\u0633\u06CC\u0627\u0631 \u0628\u0627\u0644\u0627", "\u062A\u0631\u0627\u06A9\u0645 \u062C\u0645\u0639\u06CC\u062A\u06CC \u0646\u0633\u0628\u062A\u0627\u064B \u0628\u0627\u0644\u0627", "031", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0645\u0637\u0647\u0631\u06CC \u0648 \u0631\u0628\u0627\u0637 \u0633\u0648\u0645"],
  [312, "\u0634\u0627\u0647\u06CC\u0646\u200C\u0634\u0647\u0631 (\u0641\u0631\u062F\u0648\u0633\u06CC)", "\u0634\u0645\u0627\u0644 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0634\u0627\u0647\u06CC\u0646\u200C\u0634\u0647\u0631)", 32.86, 51.552, 58, 660, 8.8, 8.8, 8.9, 7.4, 8.9, 9.6, "\u0646\u062E\u0633\u062A\u06CC\u0646 \u0634\u0647\u0631 \u0627\u0632 \u067E\u06CC\u0634 \u0637\u0631\u0627\u062D\u06CC\u200C\u0634\u062F\u0647 \u0627\u06CC\u0631\u0627\u0646 \u0628\u0627 \u062E\u06CC\u0627\u0628\u0627\u0646\u200C\u0628\u0646\u062F\u06CC \u0634\u0637\u0631\u0646\u062C\u06CC \u0628\u06CC\u200C\u0646\u0638\u06CC\u0631", "\u0641\u0627\u0635\u0644\u0647 \u06F2\u06F0 \u06A9\u06CC\u0644\u0648\u0645\u062A\u0631\u06CC \u062A\u0627 \u0645\u0631\u06A9\u0632 \u0627\u0635\u0641\u0647\u0627\u0646", "031", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0641\u0631\u062F\u0648\u0633\u06CC \u0648 \u0639\u0637\u0627\u0631 \u0634\u0627\u0647\u06CC\u0646\u200C\u0634\u0647\u0631"],
  [313, "\u0634\u0647\u0631 \u062C\u062F\u06CC\u062F \u0628\u0647\u0627\u0631\u0633\u062A\u0627\u0646", "\u062C\u0646\u0648\u0628 \u0634\u0631\u0642 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0645\u062D\u0648\u0631 \u0634\u06CC\u0631\u0627\u0632)", 32.476, 51.778, 54, 620, 8.9, 8.6, 8.7, 8.2, 8.7, 9.3, "\u0628\u0632\u0631\u06AF\u200C\u062A\u0631\u06CC\u0646 \u0634\u0647\u0631 \u062C\u062F\u06CC\u062F \u0627\u0633\u062A\u0627\u0646 \u0627\u0635\u0641\u0647\u0627\u0646\u060C \u0627\u062A\u0635\u0627\u0644 \u0628\u0647 \u0645\u062A\u0631\u0648 \u0648 \u0642\u06CC\u0645\u062A \u0645\u0646\u0627\u0633\u0628", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u0648\u0631\u0648\u062F\u06CC \u0645\u0631\u0642 \u062F\u0631 \u0633\u0627\u0639\u0627\u062A \u06A9\u0627\u0631\u0645\u0646\u062F\u06CC", "031", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0644\u0641\u062A \u0628\u0647\u0627\u0631\u0633\u062A\u0627\u0646"],
  [314, "\u0641\u0648\u0644\u0627\u062F\u0634\u0647\u0631", "\u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0645\u062D\u0648\u0631 \u0630\u0648\u0628\u200C\u0622\u0647\u0646)", 32.491, 51.408, 44, 500, 8.7, 8.5, 8.6, 6.8, 8.5, 9.1, "\u0645\u062D\u0644\u0627\u062A \u0648\u06CC\u0644\u0627\u06CC\u06CC \u0648 \u0622\u067E\u0627\u0631\u062A\u0645\u0627\u0646\u06CC \u0633\u0631\u0633\u0628\u0632 \u0628\u0627 \u0642\u06CC\u0645\u062A \u0628\u0633\u06CC\u0627\u0631 \u0627\u0642\u062A\u0635\u0627\u062F\u06CC", "\u0641\u0627\u0635\u0644\u0647 \u06F2\u06F5 \u062F\u0642\u06CC\u0642\u0647\u200C\u0627\u06CC \u062A\u0627 \u0627\u0635\u0641\u0647\u0627\u0646", "031", "\u0645\u062D\u0644\u0647 \u0628\u06F1 \u0648 \u0628\u0644\u0648\u0627\u0631 \u0645\u0637\u0647\u0631\u06CC \u0641\u0648\u0644\u0627\u062F\u0634\u0647\u0631"],
  [315, "\u0646\u062C\u0641\u200C\u0622\u0628\u0627\u062F (\u0627\u0645\u06CC\u0631\u06A9\u0628\u06CC\u0631)", "\u063A\u0631\u0628 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0646\u062C\u0641\u200C\u0622\u0628\u0627\u062F)", 32.634, 51.366, 56, 640, 8.8, 8.6, 8.6, 7, 8.8, 9.2, "\u0634\u0647\u0631 \u0628\u0632\u0631\u06AF \u0635\u0646\u0639\u062A\u06CC\u060C \u062F\u0627\u0646\u0634\u06AF\u0627\u0647\u06CC \u0648 \u062A\u062C\u0627\u0631\u06CC \u063A\u0631\u0628 \u0627\u0635\u0641\u0647\u0627\u0646 \u0628\u0627 \u0627\u0645\u06A9\u0627\u0646\u0627\u062A \u06A9\u0627\u0645\u0644", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0645\u0631\u06A9\u0632 \u06A9\u0644\u0627\u0646\u200C\u0634\u0647\u0631 \u0627\u0635\u0641\u0647\u0627\u0646", "031", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0627\u0645\u0627\u0645 \u0648 \u0627\u0645\u06CC\u0631\u06A9\u0628\u06CC\u0631 \u0646\u062C\u0641\u200C\u0622\u0628\u0627\u062F"],
  [316, "\u062E\u0645\u06CC\u0646\u06CC\u200C\u0634\u0647\u0631 (\u0645\u0646\u0638\u0631\u06CC\u0647)", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0627\u0635\u0641\u0647\u0627\u0646 (\u062E\u0645\u06CC\u0646\u06CC\u200C\u0634\u0647\u0631)", 32.685, 51.531, 52, 590, 8.6, 8.5, 8.5, 7.2, 8.6, 9.1, "\u0647\u0645\u062C\u0648\u0627\u0631\u06CC \u0645\u0633\u062A\u0642\u06CC\u0645 \u0628\u0627 \u062F\u0627\u0646\u0634\u06AF\u0627\u0647 \u0635\u0646\u0639\u062A\u06CC \u0627\u0635\u0641\u0647\u0627\u0646 \u0648 \u0634\u0647\u0631\u06A9 \u0645\u0646\u0638\u0631\u06CC\u0647 \u0646\u0648\u0633\u0627\u0632", "\u062A\u0631\u0627\u06A9\u0645 \u0628\u0627\u0641\u062A \u0642\u062F\u06CC\u0645 \u0645\u0631\u06A9\u0632 \u0634\u0647\u0631", "031", "\u0634\u0647\u0631\u06A9 \u0645\u0646\u0638\u0631\u06CC\u0647 \u062E\u0645\u06CC\u0646\u06CC\u200C\u0634\u0647\u0631"],
  [317, "\u06A9\u0627\u0634\u0627\u0646 (\u0627\u0645\u06CC\u0631\u06A9\u0628\u06CC\u0631)", "\u0634\u0645\u0627\u0644 \u0627\u0633\u062A\u0627\u0646 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u06A9\u0627\u0634\u0627\u0646)", 33.985, 51.41, 62, 710, 8.4, 8.8, 8.8, 6.8, 9.1, 9.2, "\u0642\u0637\u0628 \u062C\u0647\u0627\u0646\u06CC \u0641\u0631\u0634\u060C \u06AF\u0644\u0627\u0628 \u0648 \u06AF\u0631\u062F\u0634\u06AF\u0631\u06CC \u062A\u0627\u0631\u06CC\u062E\u06CC (\u0628\u0627\u063A \u0641\u06CC\u0646 \u0648 \u062E\u0627\u0646\u0647\u200C\u0647\u0627\u06CC \u062A\u0627\u0631\u06CC\u062E\u06CC)", "\u06AF\u0631\u0645\u0627\u06CC \u062A\u0627\u0628\u0633\u062A\u0627\u0646 \u06A9\u0648\u06CC\u0631\u06CC", "031", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0645\u06CC\u0631\u06A9\u0628\u06CC\u0631 \u06A9\u0627\u0634\u0627\u0646"],
  [318, "\u0634\u0647\u0631\u0636\u0627 (\u067E\u0627\u0633\u062F\u0627\u0631\u0627\u0646)", "\u062C\u0646\u0648\u0628 \u0627\u0633\u062A\u0627\u0646 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0634\u0647\u0631\u0636\u0627)", 32.009, 51.866, 46, 520, 8.9, 8.5, 8.5, 6, 8.9, 9.1, "\u0622\u0628\u200C\u0648\u0647\u0648\u0627\u06CC \u0645\u0637\u0628\u0648\u0639 \u0648 \u0634\u0627\u0647\u0631\u0627\u0647 \u062A\u0631\u0627\u0646\u0632\u06CC\u062A\u06CC \u0627\u0635\u0641\u0647\u0627\u0646-\u0634\u06CC\u0631\u0627\u0632", "\u0641\u0627\u0635\u0644\u0647 \u06F7\u06F0 \u06A9\u06CC\u0644\u0648\u0645\u062A\u0631\u06CC \u062A\u0627 \u0627\u0635\u0641\u0647\u0627\u0646", "031", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u067E\u0627\u0633\u062F\u0627\u0631\u0627\u0646 \u0634\u0647\u0631\u0636\u0627"],
  [319, "\u0632\u0631\u06CC\u0646\u200C\u0634\u0647\u0631 (\u0644\u0646\u062C\u0627\u0646)", "\u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0633\u0627\u062D\u0644 \u0632\u0627\u06CC\u0646\u062F\u0647\u200C\u0631\u0648\u062F)", 32.389, 51.376, 48, 540, 8.5, 8.6, 8.5, 6.2, 8.7, 9, "\u0647\u0645\u062C\u0648\u0627\u0631\u06CC \u0628\u0627 \u0634\u0627\u0644\u06CC\u0632\u0627\u0631\u0647\u0627 \u0648 \u067E\u0627\u0631\u06A9 \u0633\u0627\u062D\u0644\u06CC \u0632\u0627\u06CC\u0646\u062F\u0647\u200C\u0631\u0648\u062F\u060C \u0642\u0637\u0628 \u0634\u0627\u063A\u0644\u06CC\u0646 \u0630\u0648\u0628\u200C\u0622\u0647\u0646", "\u0646\u0632\u062F\u06CC\u06A9\u06CC \u0628\u0647 \u0635\u0646\u0627\u06CC\u0639 \u0628\u0632\u0631\u06AF", "031", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0628\u0627\u0647\u0646\u0631 \u0632\u0631\u06CC\u0646\u200C\u0634\u0647\u0631"],
  [320, "\u0645\u0628\u0627\u0631\u06A9\u0647 (\u062E\u06CC\u0627\u0628\u0627\u0646 \u0627\u0645\u0627\u0645)", "\u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0645\u0628\u0627\u0631\u06A9\u0647)", 32.346, 51.504, 46, 520, 8.6, 8.6, 8.5, 6, 8.8, 9.2, "\u0642\u0637\u0628 \u0635\u0646\u0639\u062A\u06CC \u0641\u0648\u0644\u0627\u062F \u0645\u0628\u0627\u0631\u06A9\u0647\u060C \u0641\u0636\u0627\u06CC \u0633\u0628\u0632 \u0634\u0647\u0631\u06CC \u0639\u0627\u0644\u06CC \u0648 \u0631\u0648\u0646\u0642 \u0627\u0642\u062A\u0635\u0627\u062F\u06CC", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0645\u0631\u06A9\u0632 \u0627\u0633\u062A\u0627\u0646", "031", "\u0628\u0644\u0648\u0627\u0631 \u0646\u06CC\u06A9\u0628\u062E\u062A \u0648 \u0627\u0645\u0627\u0645 \u0645\u0628\u0627\u0631\u06A9\u0647"],
  [321, "\u0641\u0644\u0627\u0648\u0631\u062C\u0627\u0646 \u0648 \u0627\u0628\u0631\u06CC\u0634\u0645", "\u063A\u0631\u0628 \u0627\u0635\u0641\u0647\u0627\u0646 (\u062D\u0627\u0634\u06CC\u0647 \u0632\u0627\u06CC\u0646\u062F\u0647\u200C\u0631\u0648\u062F)", 32.555, 51.509, 48, 550, 8.8, 8.4, 8.4, 6.8, 8.6, 9.3, "\u0646\u0632\u062F\u06CC\u06A9\u200C\u062A\u0631\u06CC\u0646 \u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0628\u0627\u063A\u06CC \u0628\u0647 \u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u0627\u0635\u0641\u0647\u0627\u0646", "\u062A\u0631\u062F\u062F \u0628\u0627\u0644\u0627 \u062F\u0631 \u0628\u0632\u0631\u06AF\u0631\u0627\u0647 \u0630\u0648\u0628\u200C\u0622\u0647\u0646", "031", "\u0628\u0644\u0648\u0627\u0631 \u0637\u0627\u0644\u0642\u0627\u0646\u06CC \u0641\u0644\u0627\u0648\u0631\u062C\u0627\u0646"],
  [322, "\u06AF\u0644\u067E\u0627\u06CC\u06AF\u0627\u0646", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0627\u0633\u062A\u0627\u0646 \u0627\u0635\u0641\u0647\u0627\u0646 (\u06AF\u0644\u067E\u0627\u06CC\u06AF\u0627\u0646)", 33.453, 50.288, 45, 510, 9.2, 8.6, 8.4, 5.5, 9.1, 8.8, "\u0637\u0628\u06CC\u0639\u062A \u0633\u0631\u0633\u0628\u0632\u060C \u0633\u062F \u06A9\u0648\u0686\u0631\u06CC \u0648 \u0622\u0631\u0627\u0645\u0634 \u0648 \u0627\u0645\u0646\u06CC\u062A \u0628\u0633\u06CC\u0627\u0631 \u0628\u0627\u0644\u0627", "\u0641\u0627\u0635\u0644\u0647 \u0627\u0632 \u0645\u0631\u06A9\u0632 \u0627\u0633\u062A\u0627\u0646 \u0627\u0635\u0641\u0647\u0627\u0646", "031", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0647\u0641\u062F\u0647 \u0634\u0647\u0631\u06CC\u0648\u0631 \u06AF\u0644\u067E\u0627\u06CC\u06AF\u0627\u0646"],
  [323, "\u062E\u0648\u0627\u0646\u0633\u0627\u0631", "\u063A\u0631\u0628 \u0627\u0633\u062A\u0627\u0646 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0628\u0627\u063A\u200C\u0634\u0647\u0631 \u062E\u0648\u0627\u0646\u0633\u0627\u0631)", 33.22, 50.315, 48, 540, 9.6, 8.7, 8.3, 5.2, 9.4, 7.4, "\u067E\u0627\u0631\u06A9 \u0645\u0644\u06CC \u0633\u0631\u0686\u0634\u0645\u0647\u060C \u0686\u0634\u0645\u0647\u200C\u0633\u0627\u0631\u0647\u0627 \u0648 \u067E\u0627\u06A9\u200C\u062A\u0631\u06CC\u0646 \u0647\u0648\u0627\u06CC \u06A9\u0648\u0647\u0633\u062A\u0627\u0646\u06CC \u0627\u0633\u062A\u0627\u0646", "\u0645\u0633\u06CC\u0631 \u06A9\u0648\u0647\u0633\u062A\u0627\u0646\u06CC \u0648 \u0632\u0645\u0633\u062A\u0627\u0646 \u0633\u0631\u062F", "031", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0627\u0645\u0627\u0645 \u0648 \u0633\u0631\u0686\u0634\u0645\u0647 \u062E\u0648\u0627\u0646\u0633\u0627\u0631"],
  [324, "\u0646\u0637\u0646\u0632", "\u0634\u0645\u0627\u0644 \u0627\u0633\u062A\u0627\u0646 \u0627\u0635\u0641\u0647\u0627\u0646 (\u067E\u0627\u06CC\u0647 \u06A9\u0631\u06A9\u0633)", 33.512, 51.916, 44, 500, 9.3, 8.5, 8.3, 6, 9.2, 8.2, "\u0628\u0627\u063A\u200C\u0634\u0647\u0631 \u062A\u0627\u0631\u06CC\u062E\u06CC \u062F\u0631 \u062F\u0627\u0645\u0646\u0647 \u06A9\u0648\u0647 \u06A9\u0631\u06A9\u0633 \u0628\u0627 \u0622\u0628\u200C\u0648\u0647\u0648\u0627\u06CC \u06CC\u06CC\u0644\u0627\u0642\u06CC", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u06A9\u0644\u0627\u0646\u200C\u0634\u0647\u0631 \u0627\u0635\u0641\u0647\u0627\u0646", "031", "\u0628\u0644\u0648\u0627\u0631 \u0637\u0627\u0644\u0642\u0627\u0646\u06CC \u0646\u0637\u0646\u0632"],
  [325, "\u0633\u0645\u06CC\u0631\u0645", "\u062C\u0646\u0648\u0628 \u0627\u0633\u062A\u0627\u0646 \u0627\u0635\u0641\u0647\u0627\u0646 (\u0628\u0627\u0645 \u0632\u0627\u06AF\u0631\u0633)", 31.414, 51.569, 38, 430, 9.7, 8.4, 8.1, 5, 9.3, 7, "\u0642\u0637\u0628 \u0633\u06CC\u0628 \u0648 \u0622\u0628\u0634\u0627\u0631\u0647\u0627\u06CC \u0627\u06CC\u0631\u0627\u0646 \u0628\u0627 \u062E\u0646\u06A9\u200C\u062A\u0631\u06CC\u0646 \u062A\u0627\u0628\u0633\u062A\u0627\u0646 \u062F\u0631 \u0627\u0633\u062A\u0627\u0646 \u0627\u0635\u0641\u0647\u0627\u0646", "\u0641\u0627\u0635\u0644\u0647 \u06F1\u06F6\u06F0 \u06A9\u06CC\u0644\u0648\u0645\u062A\u0631\u06CC \u062A\u0627 \u0627\u0635\u0641\u0647\u0627\u0646", "031", "\u0628\u0644\u0648\u0627\u0631 \u0645\u0639\u0644\u0645 \u0633\u0645\u06CC\u0631\u0645"]
];
var SHIRAZ_SEEDS = [
  [407, "\u0632\u0631\u06AF\u0631\u06CC (\u0645\u0637\u0647\u0631\u06CC \u0634\u0645\u0627\u0644\u06CC)", "\u0634\u0645\u0627\u0644 \u0645\u0631\u06A9\u0632 \u0634\u06CC\u0631\u0627\u0632 (\u0645\u0646\u0637\u0642\u0647 \u06F1)", 29.639, 52.509, 134, 1540, 8.9, 9.2, 9.1, 8.8, 9.4, 9, "\u06CC\u06A9\u06CC \u0627\u0632 \u0644\u0648\u06A9\u0633\u200C\u062A\u0631\u06CC\u0646 \u0645\u062D\u0648\u0631\u0647\u0627\u06CC \u0634\u06CC\u0631\u0627\u0632\u060C \u0646\u0632\u062F\u06CC\u06A9 \u0627\u06CC\u0633\u062A\u06AF\u0627\u0647 \u0645\u062A\u0631\u0648 \u0645\u0637\u0647\u0631\u06CC \u0648 \u0642\u0635\u0631\u0627\u0644\u062F\u0634\u062A", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u0639\u0635\u0631\u06AF\u0627\u0647\u06CC \u0686\u0647\u0627\u0631\u0631\u0627\u0647 \u0632\u0631\u06AF\u0631\u06CC", "071", "\u0628\u0644\u0648\u0627\u0631 \u0645\u0637\u0647\u0631\u06CC \u0634\u0645\u0627\u0644\u06CC (\u0632\u0631\u06AF\u0631\u06CC)"],
  [408, "\u0628\u0644\u0648\u0627\u0631 \u0686\u0645\u0631\u0627\u0646 \u0648 \u0646\u06CC\u0627\u06CC\u0634", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0634\u06CC\u0631\u0627\u0632 (\u0645\u0646\u0637\u0642\u0647 \u06F6)", 29.656, 52.482, 126, 1450, 9.4, 9, 9, 8.4, 9.3, 8.8, "\u067E\u0627\u062A\u0648\u0642 \u067E\u06CC\u0627\u062F\u0647\u200C\u0631\u0648\u06CC\u060C \u0647\u062A\u0644\u200C\u0647\u0627\u060C \u0628\u06CC\u0645\u0627\u0631\u0633\u062A\u0627\u0646\u200C\u0647\u0627 \u0648 \u0628\u0631\u062C\u200C\u0647\u0627\u06CC \u0645\u0633\u06A9\u0648\u0646\u06CC \u0631\u0648 \u0628\u0647 \u0628\u0627\u063A\u0627\u062A", "\u0634\u0644\u0648\u063A\u06CC \u0634\u0628\u200C\u0647\u0627\u06CC \u062A\u0639\u0637\u06CC\u0644 \u062F\u0631 \u0628\u0644\u0648\u0627\u0631 \u0686\u0645\u0631\u0627\u0646", "071", "\u0628\u0644\u0648\u0627\u0631 \u0686\u0645\u0631\u0627\u0646 \u0648 \u0646\u06CC\u0627\u06CC\u0634"],
  [409, "\u0642\u062F\u0648\u0633\u06CC \u063A\u0631\u0628\u06CC \u0648 \u0634\u0631\u0642\u06CC", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0634\u06CC\u0631\u0627\u0632 (\u0645\u0646\u0637\u0642\u0647 \u06F1 \u0648 \u06F6)", 29.642, 52.478, 120, 1380, 9, 9, 9.1, 7.8, 9.2, 9.1, "\u062E\u06CC\u0627\u0628\u0627\u0646\u200C\u0647\u0627\u06CC \u0639\u0631\u06CC\u0636\u060C \u06A9\u0627\u0641\u0647\u200C\u0647\u0627 \u0648 \u0622\u067E\u0627\u0631\u062A\u0645\u0627\u0646\u200C\u0647\u0627\u06CC \u0646\u0648\u0633\u0627\u0632 \u0628\u0633\u06CC\u0627\u0631 \u062E\u0648\u0634\u200C\u0646\u0642\u0634\u0647", "\u062A\u0631\u062F\u062F \u0628\u0627\u0644\u0627 \u062F\u0631 \u0633\u0627\u0639\u0627\u062A \u0634\u0628\u0627\u0646\u0647", "071", "\u0628\u0644\u0648\u0627\u0631 \u0642\u062F\u0648\u0633\u06CC \u063A\u0631\u0628\u06CC"],
  [410, "\u062A\u0627\u0686\u0627\u0631\u0627 (\u0645\u06CC\u0631\u0632\u0627\u06CC \u0634\u06CC\u0631\u0627\u0632\u06CC)", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0634\u06CC\u0631\u0627\u0632 (\u0645\u0646\u0637\u0642\u0647 \u06F6)", 29.682, 52.454, 96, 1100, 9.1, 8.9, 9, 9.2, 9, 9, "\u0627\u06CC\u0633\u062A\u06AF\u0627\u0647 \u0645\u062A\u0631\u0648 \u0645\u06CC\u0631\u0632\u0627\u06CC \u0634\u06CC\u0631\u0627\u0632\u06CC \u0648 \u0634\u0627\u0647\u062F\u060C \u062F\u0633\u062A\u0631\u0633\u06CC \u0633\u0631\u06CC\u0639 \u0628\u0647 \u0645\u0639\u0627\u0644\u06CC\u200C\u0622\u0628\u0627\u062F \u0648 \u0628\u0632\u0631\u06AF\u0631\u0627\u0647", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u067E\u0644 \u0645\u0639\u0627\u0644\u06CC\u200C\u0622\u0628\u0627\u062F \u062F\u0631 \u0633\u0627\u0639\u062A \u067E\u06CC\u06A9", "071", "\u0628\u0644\u0648\u0627\u0631 \u0645\u06CC\u0631\u0632\u0627\u06CC \u0634\u06CC\u0631\u0627\u0632\u06CC (\u062A\u0627\u0686\u0627\u0631\u0627)"],
  [411, "\u067E\u0627\u0633\u062F\u0627\u0631\u0627\u0646 \u0648 \u0632\u0631\u0647\u06CC", "\u063A\u0631\u0628 \u0645\u0631\u06A9\u0632 \u0634\u06CC\u0631\u0627\u0632 (\u0645\u0646\u0637\u0642\u0647 \u06F1 \u0648 \u06F4)", 29.621, 52.482, 98, 1130, 8.7, 9, 8.9, 7.6, 9, 9.2, "\u062E\u06CC\u0627\u0628\u0627\u0646\u200C\u0647\u0627\u06CC \u0627\u0635\u06CC\u0644 \u0648 \u067E\u0631\u0631\u0648\u0646\u0642 \u0628\u0627 \u062F\u0633\u062A\u0631\u0633\u06CC \u06A9\u0627\u0645\u0644 \u062F\u0631\u0645\u0627\u0646\u06CC\u060C \u0622\u0645\u0648\u0632\u0634\u06CC \u0648 \u062A\u062C\u0627\u0631\u06CC", "\u0634\u0644\u0648\u063A\u06CC \u062A\u0642\u0627\u0637\u0639 \u0632\u0631\u0647\u06CC \u0648 \u0628\u0627\u0647\u0646\u0631", "071", "\u0628\u0644\u0648\u0627\u0631 \u067E\u0627\u0633\u062F\u0627\u0631\u0627\u0646 \u0648 \u0627\u0633\u062A\u0642\u0644\u0627\u0644"],
  [412, "\u0627\u0631\u0645 \u0648 \u062C\u0645\u0647\u0648\u0631\u06CC", "\u0634\u0645\u0627\u0644 \u0645\u0631\u06A9\u0632 \u0634\u06CC\u0631\u0627\u0632 (\u0645\u0646\u0637\u0642\u0647 \u06F1)", 29.634, 52.524, 118, 1360, 9.1, 9.1, 9, 8.2, 9.3, 8.5, "\u0647\u0645\u062C\u0648\u0627\u0631\u06CC \u0628\u0627 \u0628\u0627\u063A \u062C\u0647\u0627\u0646\u06CC \u0627\u0631\u0645 \u0648 \u062F\u0627\u0646\u0634\u06AF\u0627\u0647 \u0634\u06CC\u0631\u0627\u0632\u060C \u0628\u0627\u0641\u062A \u0641\u0631\u0647\u0646\u06AF\u06CC \u0645\u0645\u062A\u0627\u0632", "\u0645\u062D\u062F\u0648\u062F\u06CC\u062A \u067E\u0627\u0631\u06A9 \u062F\u0631 \u0627\u0637\u0631\u0627\u0641 \u0645\u06CC\u062F\u0627\u0646 \u0627\u0631\u0645", "071", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0631\u0645 \u0648 \u0622\u0632\u0627\u062F\u06CC"],
  [413, "\u0634\u0647\u0631\u06A9 \u06AF\u0644\u0633\u062A\u0627\u0646 \u0648 \u0635\u0646\u0627\u06CC\u0639", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0634\u06CC\u0631\u0627\u0632 (\u0645\u0646\u0637\u0642\u0647 \u06F1\u06F0)", 29.732, 52.425, 78, 890, 9.3, 8.7, 8.8, 7.4, 8.8, 8.6, "\u0647\u0648\u0627\u06CC \u062E\u0646\u06A9 \u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0634\u06CC\u0631\u0627\u0632\u060C \u0646\u0645\u0627\u06CC\u0634\u06AF\u0627\u0647 \u0628\u06CC\u0646\u200C\u0627\u0644\u0645\u0644\u0644\u06CC \u0648 \u0645\u062C\u062A\u0645\u0639 \u062E\u0644\u06CC\u062C \u0641\u0627\u0631\u0633", "\u0641\u0627\u0635\u0644\u0647 \u0646\u0633\u0628\u06CC \u062A\u0627 \u0645\u0631\u06A9\u0632 \u062A\u0627\u0631\u06CC\u062E\u06CC \u0634\u06CC\u0631\u0627\u0632", "071", "\u0628\u0644\u0648\u0627\u0631 \u0639\u0644\u0627\u0645\u0647 \u0627\u0645\u06CC\u0646\u06CC \u0634\u0647\u0631\u06A9 \u06AF\u0644\u0633\u062A\u0627\u0646"],
  [414, "\u06AF\u0644\u062F\u0634\u062A \u0645\u0639\u0627\u0644\u06CC\u200C\u0622\u0628\u0627\u062F", "\u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0634\u06CC\u0631\u0627\u0632 (\u0645\u0646\u0637\u0642\u0647 \u06F6)", 29.662, 52.461, 112, 1280, 9.2, 8.9, 9, 8.6, 9.1, 9, "\u0641\u0631\u0639\u06CC\u200C\u0647\u0627\u06CC \u062F\u0646\u062C \u0648 \u0622\u0631\u0627\u0645 \u062F\u0631 \u0642\u0644\u0628 \u0645\u0639\u0627\u0644\u06CC\u200C\u0622\u0628\u0627\u062F \u0648 \u0641\u0631\u0647\u0646\u06AF\u200C\u0634\u0647\u0631", "\u0642\u06CC\u0645\u062A \u0646\u0633\u0628\u062A\u0627\u064B \u0628\u0627\u0644\u0627", "071", "\u06AF\u0644\u062F\u0634\u062A \u06F1 \u0648 \u06F2 \u0645\u0639\u0627\u0644\u06CC\u200C\u0622\u0628\u0627\u062F"],
  [415, "\u0628\u0644\u0648\u0627\u0631 \u0645\u062F\u0631\u0633 \u0648 \u06A9\u0627\u0648\u0647", "\u0634\u0631\u0642 \u0634\u06CC\u0631\u0627\u0632 (\u0645\u0646\u0637\u0642\u0647 \u06F2 \u0648 \u06F3)", 29.592, 52.568, 68, 780, 8.4, 8.7, 8.7, 9.4, 8.5, 9.4, "\u067E\u0648\u0634\u0634 \u06A9\u0627\u0645\u0644 \u062E\u0637 \u06F1 \u0645\u062A\u0631\u0648 \u0634\u06CC\u0631\u0627\u0632 (\u06A9\u0627\u0648\u0647\u060C \u062C\u0627\u0646\u0628\u0627\u0632\u0627\u0646\u060C \u063A\u062F\u06CC\u0631) \u0648 \u062F\u0633\u062A\u0631\u0633\u06CC \u0628\u0647 \u0641\u0631\u0648\u062F\u06AF\u0627\u0647", "\u0628\u0627\u0641\u062A \u0646\u0627\u0647\u0645\u06AF\u0648\u0646 \u062F\u0631 \u0628\u0631\u062E\u06CC \u06A9\u0648\u0686\u0647\u200C\u0647\u0627\u06CC \u0641\u0631\u0639\u06CC", "071", "\u0628\u0644\u0648\u0627\u0631 \u0645\u062F\u0631\u0633"],
  [416, "\u0634\u0647\u0631\u06A9 \u0648\u0627\u0644\u0641\u062C\u0631 \u0648 \u0628\u0627\u0647\u0646\u0631", "\u062C\u0646\u0648\u0628 \u063A\u0631\u0628 \u0634\u06CC\u0631\u0627\u0632 (\u0645\u0646\u0637\u0642\u0647 \u06F4 \u0648 \u06F9)", 29.589, 52.465, 76, 870, 8.7, 8.6, 8.7, 6.8, 8.7, 9.3, "\u062E\u06CC\u0627\u0628\u0627\u0646\u200C\u0628\u0646\u062F\u06CC \u0645\u0646\u0638\u0645\u060C \u067E\u0627\u0631\u06A9 \u062C\u0646\u062A \u0648 \u0622\u067E\u0627\u0631\u062A\u0645\u0627\u0646\u200C\u0647\u0627\u06CC \u0646\u0648\u0633\u0627\u0632 \u0628\u0627 \u0642\u06CC\u0645\u062A \u0645\u062A\u0639\u0627\u062F\u0644", "\u0641\u0627\u0635\u0644\u0647 \u0627\u0632 \u0627\u06CC\u0633\u062A\u06AF\u0627\u0647 \u0645\u062A\u0631\u0648 \u062E\u0637 \u06F1", "071", "\u0628\u0644\u0648\u0627\u0631 \u0641\u062C\u0631 \u0648 \u0627\u0645\u06CC\u0631\u06A9\u0628\u06CC\u0631"],
  [417, "\u0627\u0637\u0644\u0633 \u0648 \u062F\u0631\u0648\u0627\u0632\u0647 \u0642\u0631\u0622\u0646", "\u0634\u0645\u0627\u0644 \u0634\u0631\u0642 \u0634\u06CC\u0631\u0627\u0632 (\u0645\u0646\u0637\u0642\u0647 \u06F3)", 29.632, 52.559, 92, 1050, 8.9, 8.8, 8.8, 7.4, 9, 8.3, "\u0647\u0645\u062C\u0648\u0627\u0631\u06CC \u0628\u0627 \u062D\u0627\u0641\u0638\u06CC\u0647\u060C \u0628\u0627\u063A \u062C\u0647\u0627\u0646\u200C\u0646\u0645\u0627 \u0648 \u0647\u062A\u0644\u200C\u0647\u0627\u06CC \u067E\u0646\u062C\u200C\u0633\u062A\u0627\u0631\u0647 \u0634\u06CC\u0631\u0627\u0632", "\u062A\u0631\u0627\u0641\u06CC\u06A9 \u06AF\u0631\u062F\u0634\u06AF\u0631\u06CC \u062F\u0631 \u0627\u06CC\u0627\u0645 \u062A\u0639\u0637\u06CC\u0644", "071", "\u0628\u0644\u0648\u0627\u0631 \u0647\u0641\u062A\u200C\u062A\u0646 \u0648 \u0627\u0637\u0644\u0633"],
  [418, "\u0645\u0631\u0648\u062F\u0634\u062A (\u062E\u06CC\u0627\u0628\u0627\u0646 \u0627\u0646\u0642\u0644\u0627\u0628)", "\u0634\u0645\u0627\u0644 \u0634\u06CC\u0631\u0627\u0632 (\u067E\u0627\u06CC\u062A\u062E\u062A \u062A\u062E\u062A\u200C\u062C\u0645\u0634\u06CC\u062F)", 29.874, 52.8025, 48, 550, 8.9, 8.5, 8.5, 6.5, 8.8, 9.5, "\u062F\u0648\u0645\u06CC\u0646 \u0634\u0647\u0631 \u067E\u0631\u062C\u0645\u0639\u06CC\u062A \u0641\u0627\u0631\u0633 \u062F\u0631 \u0647\u0645\u062C\u0648\u0627\u0631\u06CC \u062A\u062E\u062A\u200C\u062C\u0645\u0634\u06CC\u062F\u060C \u0632\u0645\u06CC\u0646 \u06A9\u0627\u0645\u0644\u0627\u064B \u0645\u0633\u0637\u062D", "\u0641\u0627\u0635\u0644\u0647 \u06F4\u06F0 \u06A9\u06CC\u0644\u0648\u0645\u062A\u0631\u06CC \u062A\u0627 \u0634\u06CC\u0631\u0627\u0632", "071", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0627\u0646\u0642\u0644\u0627\u0628 \u0645\u0631\u0648\u062F\u0634\u062A"],
  [419, "\u062C\u0647\u0631\u0645 (\u0628\u0644\u0648\u0627\u0631 \u0641\u0631\u062F\u0648\u0633\u06CC)", "\u062C\u0646\u0648\u0628 \u0627\u0633\u062A\u0627\u0646 \u0641\u0627\u0631\u0633 (\u0628\u0627\u063A\u200C\u0634\u0647\u0631 \u062C\u0647\u0631\u0645)", 28.5, 53.56, 46, 520, 8.8, 8.5, 8.5, 5.8, 8.9, 9.1, "\u0642\u0637\u0628 \u0645\u0631\u06A9\u0628\u0627\u062A \u0648 \u0646\u062E\u0644\u0633\u062A\u0627\u0646\u200C\u0647\u0627\u06CC \u062C\u0646\u0648\u0628 \u06A9\u0634\u0648\u0631\u060C \u062F\u0627\u0646\u0634\u06AF\u0627\u0647 \u0639\u0644\u0648\u0645 \u067E\u0632\u0634\u06A9\u06CC \u062C\u0647\u0631\u0645", "\u0647\u0648\u0627\u06CC \u06AF\u0631\u0645 \u062F\u0631 \u062A\u0627\u0628\u0633\u062A\u0627\u0646", "071", "\u0628\u0644\u0648\u0627\u0631 \u0641\u0631\u062F\u0648\u0633\u06CC \u0648 \u062C\u0627\u0646\u0628\u0627\u0632\u0627\u0646 \u062C\u0647\u0631\u0645"],
  [420, "\u0641\u0633\u0627 (\u0628\u0644\u0648\u0627\u0631 \u0635\u0627\u062D\u0628\u200C\u0627\u0644\u0632\u0645\u0627\u0646)", "\u0634\u0631\u0642 \u0627\u0633\u062A\u0627\u0646 \u0641\u0627\u0631\u0633 (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0641\u0633\u0627)", 28.938, 53.648, 44, 500, 8.8, 8.5, 8.4, 5.8, 8.9, 9, "\u0645\u0631\u06A9\u0632 \u062F\u0627\u0646\u0634\u06AF\u0627\u0647\u06CC \u0648 \u062F\u0631\u0645\u0627\u0646\u06CC \u0634\u0631\u0642 \u0641\u0627\u0631\u0633 \u0628\u0627 \u0634\u0647\u0631\u0633\u0627\u0632\u06CC \u0645\u0646\u0638\u0645", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0645\u0631\u06A9\u0632 \u0627\u0633\u062A\u0627\u0646", "071", "\u0628\u0644\u0648\u0627\u0631 \u0635\u0627\u062D\u0628\u200C\u0627\u0644\u0632\u0645\u0627\u0646 \u0641\u0633\u0627"],
  [421, "\u0644\u0627\u0631 (\u0634\u0647\u0631 \u062C\u062F\u06CC\u062F \u0644\u0627\u0631)", "\u062C\u0646\u0648\u0628 \u0627\u0633\u062A\u0627\u0646 \u0641\u0627\u0631\u0633 (\u0644\u0627\u0631\u0633\u062A\u0627\u0646)", 27.683, 54.34, 52, 590, 8.5, 8.6, 8.6, 5.5, 9.2, 9.3, "\u0634\u0647\u0631 \u062C\u062F\u06CC\u062F \u0634\u0637\u0631\u0646\u062C\u06CC \u0648 \u0645\u062F\u0631\u0646 \u0644\u0627\u0631\u060C \u0641\u0631\u0648\u062F\u06AF\u0627\u0647 \u0628\u06CC\u0646\u200C\u0627\u0644\u0645\u0644\u0644\u06CC \u0648 \u0631\u0648\u0646\u0642 \u062A\u062C\u0627\u0631\u06CC \u062E\u0644\u06CC\u062C\u200C\u0641\u0627\u0631\u0633", "\u0627\u0642\u0644\u06CC\u0645 \u06AF\u0631\u0645\u0633\u06CC\u0631\u06CC", "071", "\u0628\u0644\u0648\u0627\u0631 \u0641\u0631\u0647\u0646\u06AF \u0634\u0647\u0631 \u062C\u062F\u06CC\u062F \u0644\u0627\u0631"],
  [422, "\u06A9\u0627\u0632\u0631\u0648\u0646 (\u0628\u0644\u0648\u0627\u0631 \u067E\u0631\u06CC\u0634\u0627\u0646)", "\u063A\u0631\u0628 \u0627\u0633\u062A\u0627\u0646 \u0641\u0627\u0631\u0633 (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u06A9\u0627\u0632\u0631\u0648\u0646)", 29.619, 51.654, 42, 480, 8.9, 8.4, 8.4, 5.8, 8.8, 9.1, "\u067E\u0627\u06CC\u062A\u062E\u062A \u0633\u0627\u0633\u0627\u0646\u06CC \u0628\u06CC\u0634\u0627\u067E\u0648\u0631 \u0648 \u062F\u0634\u062A\u200C\u0647\u0627\u06CC \u0633\u0631\u0633\u0628\u0632 \u0646\u0631\u06AF\u0633\u200C\u0632\u0627\u0631", "\u0641\u0627\u0635\u0644\u0647 \u0627\u0632 \u0645\u0631\u06A9\u0632 \u0627\u0633\u062A\u0627\u0646", "071", "\u062E\u06CC\u0627\u0628\u0627\u0646 \u0633\u0644\u0645\u0627\u0646 \u0648 \u0634\u0647\u062F\u0627\u06CC \u06A9\u0627\u0632\u0631\u0648\u0646"],
  [423, "\u0622\u0628\u0627\u062F\u0647 (\u0628\u0644\u0648\u0627\u0631 \u0627\u0633\u062A\u0642\u0644\u0627\u0644)", "\u0634\u0645\u0627\u0644 \u0627\u0633\u062A\u0627\u0646 \u0641\u0627\u0631\u0633 (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0622\u0628\u0627\u062F\u0647)", 31.16, 52.65, 40, 460, 9.1, 8.5, 8.4, 6, 9, 9.3, "\u0634\u0647\u0631 \u062C\u0647\u0627\u0646\u06CC \u0645\u0646\u0628\u062A \u0648 \u0622\u0628\u200C\u0648\u0647\u0648\u0627\u06CC \u0645\u0639\u062A\u062F\u0644 \u06A9\u0648\u0647\u0633\u062A\u0627\u0646\u06CC \u062F\u0631 \u0645\u062D\u0648\u0631 \u0634\u06CC\u0631\u0627\u0632-\u0627\u0635\u0641\u0647\u0627\u0646", "\u0641\u0627\u0635\u0644\u0647 \u062A\u0627 \u0634\u06CC\u0631\u0627\u0632", "071", "\u0628\u0644\u0648\u0627\u0631 \u0627\u0633\u062A\u0642\u0644\u0627\u0644 \u0622\u0628\u0627\u062F\u0647"],
  [424, "\u062F\u0627\u0631\u0627\u0628 (\u0628\u0644\u0648\u0627\u0631 \u0637\u0627\u0644\u0642\u0627\u0646\u06CC)", "\u062C\u0646\u0648\u0628 \u0634\u0631\u0642 \u0641\u0627\u0631\u0633 (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u062F\u0627\u0631\u0627\u0628)", 28.751, 54.544, 40, 450, 8.9, 8.3, 8.3, 5.5, 8.8, 9, "\u0634\u0647\u0631 \u062A\u0627\u0631\u06CC\u062E\u06CC \u062F\u0627\u0631\u0627\u0628\u06AF\u0631\u062F \u0648 \u0628\u0627\u063A\u0627\u062A \u0645\u0631\u06A9\u0628\u0627\u062A \u0648 \u06AF\u0644 \u0645\u062D\u0645\u062F\u06CC", "\u0641\u0627\u0635\u0644\u0647 \u0627\u0632 \u0634\u06CC\u0631\u0627\u0632", "071", "\u0628\u0644\u0648\u0627\u0631 \u0637\u0627\u0644\u0642\u0627\u0646\u06CC \u062F\u0627\u0631\u0627\u0628"],
  [425, "\u0641\u06CC\u0631\u0648\u0632\u0622\u0628\u0627\u062F (\u062E\u06CC\u0627\u0628\u0627\u0646 \u0631\u0648\u0632\u0628\u0647)", "\u062C\u0646\u0648\u0628 \u0634\u06CC\u0631\u0627\u0632 (\u0634\u0647\u0631\u0633\u062A\u0627\u0646 \u0641\u06CC\u0631\u0648\u0632\u0622\u0628\u0627\u062F)", 28.843, 52.57, 38, 430, 9, 8.3, 8.3, 5.8, 8.8, 9.1, "\u0634\u0647\u0631 \u0628\u0627\u0633\u062A\u0627\u0646\u06CC \u06AF\u0648\u0631 \u0648 \u06A9\u0627\u062E \u0627\u0631\u062F\u0634\u06CC\u0631 \u0628\u0627\u0628\u06A9\u0627\u0646 \u062F\u0631 \u06F9\u06F0 \u06A9\u06CC\u0644\u0648\u0645\u062A\u0631\u06CC \u062C\u0646\u0648\u0628 \u0634\u06CC\u0631\u0627\u0632", "\u062F\u0631 \u062D\u0627\u0644 \u062A\u06A9\u0645\u06CC\u0644 \u0628\u0632\u0631\u06AF\u0631\u0627\u0647 \u0634\u06CC\u0631\u0627\u0632-\u0641\u06CC\u0631\u0648\u0632\u0622\u0628\u0627\u062F", "071", "\u0628\u0644\u0648\u0627\u0631 \u067E\u0627\u0633\u062F\u0627\u0631\u0627\u0646 \u0641\u06CC\u0631\u0648\u0632\u0622\u0628\u0627\u062F"]
];
